local config = {
  ui_story_5060_50600101_1_dialog_content = "Sebuah kontes fotografi di distrik perbelanjaan, dan hadiah utamanya adalah liburan ke luar negeri untuk dua orang!",
  ui_story_5060_50600101_2_dialog_content = "Dengan itu, aku bisa pergi liburan romantis bersama <color=#FFB400>Kobayashi</color>!",
  ui_story_5060_50600101_3_dialog_content = "Dan cara terbaik untuk menang adalah dengan mengambil foto pemandangan dari dunia kita sendiri! Aku memang jenius, ya?",
  ui_story_5060_50600101_4_dialog_content = "Hei, Tohru. Bukankah kamu bilang kita akan kembali untuk mengumpulkan beberapa bahan makanan eksotis?",
  ui_story_5060_50600101_5_dialog_content = "Mengapa kamu masih membahas itu, Elma? Jangan khawatir, kita bisa mengumpulkan semua bahan yang kita butuhkan sambil berfoto!",
  ui_story_5060_50600101_6_dialog_content = "Yah, sudahlah. Kita nggak punya waktu untuk berdebat soal ini. Silakan, lewat sini semua!",
  ui_story_5060_50600101_7_dialog_content = [[
Mengakt

Text: for</color>]],
  ui_story_5060_50600101_8_dialog_content = "Baiklah teman-teman, bersiaplah untuk akhirnya melihat kampung halaman kita!",
  ui_story_5060_50600101_9_dialog_content = "Hah? T-Tunggu...",
  ui_story_5060_50600101_10_dialog_content = "<size=50>Tempat apa ini?!</size>",
  ui_story_5060_50600101_11_dialog_content = "Mengaktifkan Gerbang Teleportasi Dunia! Hrrrng—! Ayo, aktifkan!",
  ui_story_5060_50600101_12_dialog_content = "Aneh, portalnya sama sekali tidak mau menyala.",
  ui_story_5060_50600101_13_dialog_content = "Oh, ini tidak baik... Apakah Kanna dan Elma juga terjebak di sini tanpa jalan kembali?",
  ui_story_5060_50600101_14_dialog_content = "Oke, tenang saja dan perhatikan sekitar... Beberapa hal di dunia ini bisa aku kenali.",
  ui_story_5060_50600101_15_dialog_content = "Tidak jauh berbeda dari dunia Kobayashi. Misalnya, di sini juga ada minimarket dan transportasi umum...",
  ui_story_5060_50600101_16_dialog_content = "Yah, aku akan pergi dengan boneka mekanik ini.",
  ui_story_5060_50600101_17_dialog_content = "Selera Anda sempurna, Ma'am! Putri Anda pasti akan sangat menyukai hadiah yang lucu dan patuh ini!",
  ui_story_5060_50600101_18_dialog_content = "Tolong bungkus cepat. Aku harus mengejar pesawat ke Shuttle Hub.",
  ui_story_5060_50600101_19_dialog_content = "Siap, laksanakan, Bu! Terima kasih banyak sudah berbelanja bersama kami!",
  ui_story_5060_50600101_20_dialog_content = "Kamu! Mengganggu ketertiban jalan dengan <color=#FFB400>Luminatics</color> sangat dilarang di sini!",
  ui_story_5060_50600101_21_dialog_content = "Hei, aku bicara tentang kamu! Si <color=#FFB400>demi-human</color> yang bermain api di sana! Hentikan pertunjukan jalananmu! Sekarang juga!",
  ui_story_5060_50600101_22_dialog_content = "Maaf! Sorry! Saya pergi sekarang... Aduh, itu sakit!",
  ui_story_5060_50600101_23_dialog_content = "Bagaimana bisa Dewa Cahaya memilih untuk memberkati pengacau seperti kamu dengan Luminatics...",
  ui_story_5060_50600101_24_dialog_content = "Hai! Apa yang sedang kamu lihat? Mundur! Jangan menghalangi jalan!",
  ui_story_5060_50600101_25_dialog_content = "...",
  ui_story_5060_50600101_26_dialog_content = "Apa yang terjadi? Apakah demi-human membuat masalah lagi? Jauhi mereka, semua orang...",
  ui_story_5060_50600101_27_dialog_content = "Um... Di tanah airku juga ada <color=#FFB400>ras setengah manusia</color> dan <color=#FFB400>sihir</color> yang serupa...",
  ui_story_5060_50600101_28_dialog_content = "Tapi di sini, mereka menyebutnya <color=#FFB400>Aurorian demi-human</color> dan <color=#FFB400>Luminatics</color>, bukan?",
  ui_story_5060_50600101_29_dialog_content = "Ada sesuatu yang aneh tentang <color=#FFB400>mana</color> di dunia ini, dan itu menghalangi saya untuk <color=#FFB400>kembali menjadi naga</color>. Jika bukan karena kekuatan saya yang terbatas...",
  ui_story_5060_50600101_30_dialog_content = "Aku akan mengajari para ksatria sombong ini sebuah pelajaran sekarang juga!",
  ui_story_5060_50600101_31_dialog_content = "Kastil putih yang mengapung di atas itu terlihat sangat mencurigakan. Aku yakin itu adalah markas dari para ksatria ini.",
  ui_story_5060_50600101_32_dialog_content = "Terjebak di dunia baru yang aneh dengan kekuatan yang terbatas, dan di bawah tatapan hati-hati dari beberapa penduduknya...",
  ui_story_5060_50600101_33_dialog_content = "Dalam situasi seperti ini, apakah sebaiknya aku menggunakan kekerasan untuk mengintimidasi orang-orang di sekitarku terlebih dahulu?",
  ui_story_5060_50600101_34_dialog_content = "Dengan begitu, aku bisa mengulur waktu untuk mengumpulkan kekuatan dan mencari Kanna dan yang lainnya.",
  ui_story_5060_50600101_35_dialog_content = "Urgh... Tidak, sepertinya aku perlu mengisi ulang energiku dulu. Aku penasaran, uang di dunia ini bentuknya seperti apa ya?",
  ui_story_5060_50600101_36_dialog_content = "Pastri Longzhou panggang segar! Lezat dan ringan di lidah! Hei, nona muda, ingin mencicipi?",
  ui_story_5060_50600101_37_dialog_content = "Gigitan? Apakah itu berarti gratis?",
  ui_story_5060_50600101_38_dialog_content = "Tentu saja! Cobalah dulu, dan belilah jika Anda suka rasanya. Kami bahkan menyediakan pengiriman, jadi Anda bisa mengirimkannya ke teman-teman yang jauh.",
  ui_story_5060_50600101_39_dialog_content = "(Aku perlu mengonfirmasi apakah kita bisa memakan makanan di dunia ini dengan aman atau tidak...)",
  ui_story_5060_50600101_40_dialog_content = "Hmm? Ini sebenarnya lumayan bagus!",
  ui_story_5060_50600101_41_dialog_content = "Wow! Menakjubkan!",
  ui_story_5060_50600101_42_dialog_content = "Anda menguasai sumpit dengan baik. Pernah ke <color=#FFB400>Longzhou</color>?",
  ui_story_5060_50600101_43_dialog_content = "Hah? Sama sekali tidak. Di mana tempat \"Longzhou\" ini?",
  ui_story_5060_50600101_44_dialog_content = "Ini adalah tempat kelahiran saya, sebuah benua di luar negeri dengan budaya yang berkembang pesat dan makanan yang lezat. Tempat saya, Restoran Liu, mengkhususkan diri dalam masakan Longzhou.",
  ui_story_5060_50600101_45_dialog_content = "(Longzhou... Apakah restoran ini ada hubungannya dengan naga yang sedang saya cari?)",
  ui_story_5060_50600101_46_dialog_content = "Dan tempat apa ini?",
  ui_story_5060_50600101_47_dialog_content = "Ini adalah Lumopolis Bawah, jantung dari <color=#FFB400>Astra</color>. Kami memiliki pedagang dari seluruh benua di sini—",
  ui_story_5060_50600101_48_dialog_content = "Tunggu sebentar, nona, apakah kamu tersesat?",
  ui_story_5060_50600101_49_dialog_content = "Dalam beberapa hal, iya. Sejujurnya, aku juga tidak yakin apa yang terjadi.",
  ui_story_5060_50600101_50_dialog_content = "Apakah kamu mengalami hilang ingatan atau penculikan?! Jika kamu dalam masalah, kami semua di sini untuk membantu!",
  ui_story_5060_50600101_51_dialog_content = "Bagaimana kalau masuk untuk minuman hangat dan istirahat sejenak?",
  ui_story_5060_50600101_52_dialog_content = "(Orang-orang di sini juga bisa sangat baik, lho...)",
  ui_story_5060_50600101_53_dialog_content = "Terima kasih. Aku terpisah dari teman-temanku. Aku hanya perlu menemukan mereka sebelum pulang.",
  ui_story_5060_50600101_54_dialog_content = "Ada sesuatu yang ingin kutanyakan padamu... Maaf, tapi bolehkah aku tahu namamu?",
  ui_story_5060_50600101_55_dialog_content = "Saya pemilik dan koki dari Restoran Liu. Anda bisa memanggil saya Liu saja.",
  ui_story_5060_50600101_56_dialog_content = "Kalau butuh bantuan, Nona, bilang saja kepadaku!",
  ui_story_5060_50600101_57_dialog_content = "Izinkan saya memperkenalkan diri. Namaku Tohru, dan aku ingin bertanya... May Bisakah aku bekerja di restoranmu untuk sementara waktu?",
  ui_story_5060_50600101_58_dialog_content = "Aku tahu kita baru saja bertemu, dan aku masih harus banyak belajar tentang tempat ini... Tapi kemampuanku sebagai pelayan sangat hebat!",
  ui_story_5060_50600101_59_dialog_content = "Memasak, membersihkan, dan menyambut tamu adalah seperti sifat kedua bagi saya! Saya yakin saya bisa berguna untuk restoran Anda!",
  ui_story_5060_50600101_60_dialog_content = "Ini pesanan Anda, Tahu Salju! Selamat menikmati!",
  ui_story_5060_50600101_61_dialog_content = "Wah, mengesankan! Makanan di sini disajikan sangat cepat.",
  ui_story_5060_50600101_62_dialog_content = "Berikut adalah hidangan spesial terbaru dari Chef Liu: Sup Seafood Emas! Harap berhati-hati, karena ini sangat panas!",
  ui_story_5060_50600101_63_dialog_content = "Oh, sayang sekali.",
  ui_story_5060_50600101_64_dialog_content = "Ini dia sepasang sumpit baru. Jika kamu kesulitan menggunakannya... Kami juga punya pisau dan garpu! Silakan!",
  ui_story_5060_50600101_65_dialog_content = "Tohru, kita punya beberapa pelanggan!",
  ui_story_5060_50600101_66_dialog_content = "Mengerti! Siap semua? Satu, dua, tiga—",
  ui_story_5060_50600101_67_dialog_content = "Selamat datang!",
  ui_story_5060_50600101_68_dialog_content = "Harus saya katakan, hari ini cukup mengejutkan. Jarang sekali saya melihat begitu banyak pelanggan yang terlihat begitu santai dan bahagia di sini.",
  ui_story_5060_50600101_69_dialog_content = "Penampilanmu benar-benar luar biasa, Nona Tohru! Komitmen ini dalam melayani adalah yang disebut semangat pembantu...",
  ui_story_5060_50600101_70_dialog_content = "Benar! Inilah semangat dedikasi seorang pelayan sejati!",
  ui_story_5060_50600101_71_dialog_content = "Oh sayang, aku tak pernah menyangka akan mendapatkan kesempatan untuk mencoba sesuatu yang begitu baru dan menarik di usia ini.",
  ui_story_5060_50600101_72_dialog_content = "Begitu juga untuk saya! Saya telah belajar banyak dari cara kamu menilai dan menyiapkan hidanganmu!",
  ui_story_5060_50600101_73_dialog_content = "Belajar membuat hidangan baru selalu membuat saya penasaran bagaimana ekspresi wajahnya saat saya menyajikannya untuknya...",
  ui_story_5060_50600101_74_dialog_content = "(Baiklah, aku akan belajar banyak resep yang mungkin disukai Kobayashi, dan mencobanya saat aku kembali!)",
  ui_story_5060_50600101_75_dialog_content = "Bos, kami kembali!",
  ui_story_5060_50600101_76_dialog_content = "Senang melihat kalian kembali dengan selamat. Jadi, apakah kalian menemukan <color=#FFB400>Aurorian dengan sifat naga</color> yang disebutkan oleh Nona Tohru?",
  ui_story_5060_50600101_77_dialog_content = "Tidak, tidak ada petunjuk dalam itu. Sedangkan untuk bisnis baru...",
  ui_story_5060_50600101_78_dialog_content = "Maksud kamu layanan pengiriman, kan? Jangan buru-buru; santai saja.",
  ui_story_5060_50600101_79_dialog_content = "Orang yang bertanggung jawab atas bisnis baru itu mengundurkan diri lagi, dengan alasan bahwa menawarkan layanan pengiriman di Astra terlalu berisiko.",
  ui_story_5060_50600101_80_dialog_content = "Jadi, kita harus mencari orang lain untuk menggantikan.",
  ui_story_5060_50600101_81_dialog_content = "Mengerti. Lagipula, <color=#FFB400>Eclipsite</color> cukup aktif. Mereka bisa mengganggu jalur perdagangan kapan saja.",
  ui_story_5060_50600101_82_dialog_content = "Mungkin kita perlu menyewa profesional seperti anggota Courier Union untuk menanganinya...",
  ui_story_5060_50600101_83_dialog_content = "Aku ingin bertanya, apakah \"<color=#FFB400>Eclipsites</color>\" itu semacam monster?",
  ui_story_5060_50600101_84_dialog_content = "Setiap kali orang menyebut mereka, wajah mereka menjadi pucat.",
  ui_story_5060_50600101_85_dialog_content = "Tohru, kamu tidak tahu tentang Eclipsite?!",
  ui_story_5060_50600101_86_dialog_content = "Yah, saya memang berasal dari tempat yang sangat jauh, lho.",
  ui_story_5060_50600101_87_dialog_content = "Tak bisa bayangkan seberapa jauh yang harus kita tempuh untuk tetap menjauh dari Eclipsite.",
  ui_story_5060_50600101_88_dialog_content = "Eclipsites telah menjadi bagian dari dunia ini sejak kami Aurorian membentuk sejarah kami sendiri.",
  ui_story_5060_50600101_89_dialog_content = "Mereka memiliki penampilan yang mengerikan dan kekuatan buas, sering bepergian dalam kelompok, menimbulkan kekacauan di pedesaan.",
  ui_story_5060_50600101_90_dialog_content = "Terkadang, di bawah komando pemimpin yang kuat, mereka bahkan menyerang kota dan menabur kekacauan.",
  ui_story_5060_50600101_91_dialog_content = "Tampaknya hidup di dunia ini tidak semudah yang terlihat.",
  ui_story_5060_50600101_92_dialog_content = "Haha, tapi kita semua sudah terbiasa. Semangat, dan kita masih bisa melanjutkan.",
  ui_story_5060_50600101_93_dialog_content = "Sekarang, mari kita bahas bagaimana kita bisa membantu Nona Tohru untuk menemukan jalan pulang!",
  ui_story_5060_50600101_94_dialog_content = "Terima kasih semuanya. Sejujurnya, aku tahu jalan pulang, tapi aku mengalami sedikit masalah...",
  ui_story_5060_50600101_95_dialog_content = "(Levél <color=#FFB400>mana</color> di dunia ini terlalu tidak stabil sehingga portal tidak dapat diaktifkan dengan baik...)",
  ui_story_5060_50600101_96_dialog_content = "(Saat ini, saya perlu menemukan lokasi di mana tingkat mana relatif seimbang, sehingga saya dapat menguji portal tanpa gangguan apa pun...)",
  ui_story_5060_50600101_97_dialog_content = "(Tapi aku tidak bisa meninggalkan Kanna dan yang lainnya terjebak di dunia ini...)",
  ui_story_5060_50600101_98_dialog_content = "(Aku butuh uang jika ingin bepergian dan mengumpulkan informasi juga. Tidak bisa terus mengandalkan kebaikan hati Pak Liu...)",
  ui_story_5060_50600101_99_dialog_content = "Ahh, betapa stresnya! Ini pasti yang biasa dirasakan Kobayashi sebagai kepala rumah tangga kami!",
  ui_story_5060_50600101_100_dialog_content = "Bos, kabar buruk! Pesanan pengiriman baru lagi-lagi tidak selesai!",
  ui_story_5060_50600101_101_dialog_content = "Kenapa kali ini?",
  ui_story_5060_50600101_102_dialog_content = "Menurut kurir kami, pelanggan di Umbraton diculik oleh preman dari Guild...",
  ui_story_5060_50600101_103_dialog_content = "Hah?!",
  ui_story_5060_50600101_104_dialog_content = "Terakhir kali, jembatan di depan rumah pelanggan dihancurkan oleh para Eclipsite...",
  ui_story_5060_50600101_105_dialog_content = "Dan sebelumnya, pelanggan menghilang di Secret Territory... Tidak mungkin kami bisa menjalankan bisnis seperti ini.",
  ui_story_5060_50600101_106_dialog_content = "(Layanan pengiriman? Mungkin ini kesempatan untuk menjelajahi sekitar sambil menghasilkan uang!)",
  ui_story_5060_50600101_107_dialog_content = "Pak Liu! Bagaimana kalau saya mengambil alih pekerjaan pengiriman dan menangani sisa pesanan yang belum terkirim itu?",
  ui_story_5060_50600101_108_dialog_content = "Selama aku bersikap serius, monster dan penjahat tak ada peluang melawanku!",
  ui_story_5060_50600101_109_dialog_content = "(Ini akan menjadi cara yang sempurna bagi saya untuk menghasilkan uang dan mempelajari dunia ini sambil mencari Kanna dan yang lainnya.)",
  ui_story_5060_50600101_110_dialog_content = "Namun, Nona Tohru, Anda harus tahu bahwa Eclipsites sering berkeliaran di luar kota, dan restoran kami tidak memiliki alat transportasi yang lebih baik daripada sepeda motor...",
  ui_story_5060_50600101_111_dialog_content = "Mengapa tidak lebih masuk akal untuk mencari bantuan dari kurir bersayap...",
  ui_story_5060_50600101_112_dialog_content = "Kalau bicara tentang sayap, kebetulan aku juga punya, lho!",
  ui_story_5060_50600101_113_dialog_content = "Mampu terbang adalah keterampilan penting bagi seorang pelayan profesional. Sekarang perhatikan ini... Aduh!",
  ui_story_5060_50600101_114_dialog_content = "M-Maaf, sepertinya aku mungkin makan terlalu banyak saat pertama kali tiba di sini.",
  ui_story_5060_50600101_115_dialog_content = "Kalau begitu, aku pergi sekarang!",
  ui_story_5060_50600101_116_dialog_content = [[
and the's 100% new! 100% new! 5 in 2014 a - 1 - 2  

, in the 3  - 1 - 1 -  [email protected] 0x0 0x0 theor 3c-3c3ce]],
  ui_story_5060_50600101_117_dialog_content = "Tidak apa-apa untuk melambat, lho. Keselamatan harus diutamakan!",
  ui_story_5060_50600101_118_dialog_content = "Tohru! Semoga sukses di luar sana!",
  ui_story_5060_50600101_119_dialog_content = "Mengerti! Saya akan pastikan menyelesaikan setiap pesanan dan mendapatkan banyak ulasan positif! Serahkan saja padaku—",
  ui_story_5060_50600101_120_dialog_content = "Aku datang, Astra!",
  ui_story_5060_50600101_121_dialog_content = "Gadis pengantar Dragon Maid ini benar-benar bersemangat!",
  ui_story_5060_50600201_1_dialog_content = "Dengarkan, semua orang! Jika kalian tidak menyerahkan <color=#FFB400>koleksi</color> sekarang, Caelestite akan benar-benar menghadapi kepunahan!",
  ui_story_5060_50600201_2_dialog_content = "Betul sekali! Mereka benar-benar akan punah!",
  ui_story_5060_50600201_3_dialog_content = "Sial, bajingan! Bagaimana kalian berani menyandera seseorang yang tak berdaya seperti PlayerName?!",
  ui_story_5060_50600201_4_dialog_content = "Lawan aku satu lawan satu, kalian pengecut!",
  ui_story_5060_50600201_5_dialog_content = "Benar, Kobayashi mengatakan orang harus bertarung secara adil dalam sebuah duel.",
  ui_story_5060_50600201_6_dialog_content = "Jadi, lawan aku satu lawan satu, kalian pengecut!",
  ui_story_5060_50600201_7_dialog_content = "Kata yang bagus, <color=#FFB400>Kanna</color>! Siap untuk bertarung?",
  ui_story_5060_50600201_8_dialog_content = "Ya. Berkat Tessa, energiku kembali terisi penuh.",
  ui_story_5060_50600201_9_dialog_content = "Ha-",
  ui_story_5060_50600201_10_dialog_content = "Tunggu, bukankah kamu setuju untuk bertarung satu lawan satu? Apakah kamu juga akan menyetrum sandera!?",
  ui_story_5060_50600201_11_dialog_content = "Sebenarnya, aku sama sekali tidak keberatan!",
  ui_story_5060_50600201_12_dialog_content = "Aku berhasil selamat dari pendaratan darurat, hujan deras, serangan psikis, cedera akibat kunci pas, dan bahkan benda asing yang dimasukkan ke dalam tubuhku...",
  ui_story_5060_50600201_13_dialog_content = "Setelah mengalami semua itu, kau benar-benar pikir aku takut disetrum sedikit saja?!",
  ui_story_5060_50600201_14_dialog_content = "Apa? Apakah Caelestites selalu tidak sopan seperti ini?",
  ui_story_5060_50600201_15_dialog_content = "Heh. Dengan keadaan kalian sekarang, kalian tak bisa membuat goresan sedikit pun pada Caelestite. Lagipula...",
  ui_story_5060_50600201_16_dialog_content = "Kami tidak pernah mencuri <color=#FFB400>koleksi</color> yang Anda bicarakan. Ini pasti salah paham.",
  ui_story_5060_50600201_17_dialog_content = "Jadi, berhentilah. Kalian juga harus makan, kan? Jika kita terus seperti ini, makanan bawaanku akan menjadi dingin.",
  ui_story_5060_50600201_18_dialog_content = "T-Tapi... kalian berdua adalah satu-satunya yang ada di sana saat itu hilang! Siapa lagi yang harus kita curigai?!",
  ui_story_5060_50600201_19_dialog_content = "Atau, tahu kan... kamu bisa saja menawarkan untuk membayarnya.",
  ui_story_5060_50600201_20_dialog_content = "Lalu saya sangat menyesal—",
  ui_story_5060_50600201_21_dialog_content = "<size=45>Aku tidak akan membayar satu Nightium pun. Jangan berharap!</size>",
  ui_story_5060_50600201_22_dialog_content = "Apa yang harus kita lakukan, Bos? Saya tidak bisa menghadapi mereka semua sendiri, dan kita juga tidak bisa mundur begitu saja...",
  ui_story_5060_50600201_23_dialog_content = "Kamu idiot tak berguna! Tentu saja kita tidak bisa mundur sekarang. Benda itu sangat penting bagi tuan-tuan kita...",
  ui_story_5060_50600201_24_dialog_content = "Ini dicuri oleh Aurorian setengah manusia yang terlihat lebih muda dari sepuluh tahun!",
  ui_story_5060_50600201_25_dialog_content = "Jadi sekarang kau menyalahkan gadis kecil ini? Sungguh kau tidak tahu malu.",
  ui_story_5060_50600201_26_dialog_content = "Sepertinya aku harus mengajari kau pelajaran secara keras, setelah semua.",
  ui_story_5060_50600201_27_dialog_content = "?",
  ui_story_5060_50600201_28_dialog_content = "Jangan dengarkan orang-orang jahat itu atau kebohongan mereka, Kanna.",
  ui_story_5060_50600201_29_dialog_content = "Setelah kita mengeluarkannya, aku akan berbagi satu lolipopku dengan kamu.",
  ui_story_5060_50600201_30_dialog_content = "Semakin dekat.",
  ui_story_5060_50600201_31_dialog_content = "<color=#e8d9bb>Ngungg!</color>",
  ui_story_5060_50600201_32_dialog_content = "Perasaan ini... Semakin dekat, tak ada keraguan tentang itu.",
  ui_story_5060_50600201_33_dialog_content = "<color=#e8d9bb>Berdengung—Berdengung—</color>",
  ui_story_5060_50600201_34_dialog_content = "Itu mereka!",
  ui_story_5060_50600201_35_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5060_50600201_36_dialog_content = "Nyaris saja! Aku belum terlambat, kan?!",
  ui_story_5060_50600201_37_dialog_content = "Kini aku tahu bagaimana perasaan Kobayashi saat dia bekerja keras hingga tulang untuk mengejar tenggat waktu proyek...",
  ui_story_5060_50600201_38_dialog_content = "Ehem! Mohon tunggu sebentar sementara saya mengkonfirmasi informasi kontak penerima...",
  ui_story_5060_50600201_39_dialog_content = "Halo, PlayerName! Berikut pesanan pengiriman Anda, tolong ingat untuk memberi kami ulasan bintang lima!",
  ui_story_5060_50600201_40_dialog_content = "Juga, toko ini sedang mencari anak kecil yang hilang dengan tanduk naga di kepalanya, yang bisa mengendalikan listrik. Jika Anda memiliki informasi terkait...",
  ui_story_5060_50600201_41_dialog_content = "Tohru—! Ini kamu, Tohru!",
  ui_story_5060_50600201_42_dialog_content = "K-Kanna?!",
  ui_story_5060_50600201_43_dialog_content = "Aku sudah mencarimu ke mana-mana! Aku tidak menyangka menemukanmu di sini!",
  ui_story_5060_50600201_44_dialog_content = "*Berpelukan, berpelukan* Tohru!",
  ui_story_5060_50600201_45_dialog_content = "Aku tidak tahu bahwa teman yang kamu cari ternyata wanita cantik seperti ini, Kanna...",
  ui_story_5060_50600201_46_dialog_content = "Sepertinya kita berhasil membantu mewujudkan harapannya, ya?",
  ui_story_5060_50600201_47_dialog_content = "Terima kasih banyak telah merawat Kanna!",
  ui_story_5060_50600201_48_dialog_content = "Bukan masalah!",
  ui_story_5060_50600201_49_dialog_content = "Tapi bicara tentang masalah, kita memang harus membuat preman-preman ini tahu diri.",
  ui_story_5060_50600201_50_dialog_content = "Sial—si brengsek itu benar-benar memanggil bala bantuan?",
  ui_story_5060_50600201_51_dialog_content = "Kepalaku... berputar...",
  ui_story_5060_50600201_52_dialog_content = "Tch, kukira dia orang penting! Ternyata hanya seorang pelayan!",
  ui_story_5060_50600201_53_dialog_content = "E-Eclipsite?! Siapa pembantu ini, bisa mendatangkan Eclipsite untuk bantuan?",
  ui_story_5060_50600201_54_dialog_content = "Lari! Maju mundur secara taktis!",
  ui_story_5060_50600201_55_dialog_content = "Kalau harus menebak, sepertinya Nyonya Tohru yang menarik mereka ke sini.",
  ui_story_5060_50600201_56_dialog_content = "Jadi itu Eclipsites, ya? Mereka telah mengejar saya sepanjang waktu, tetapi saya sangat khawatir terlambat sehingga saya hampir tidak menyadari mereka.",
  ui_story_5060_50600201_57_dialog_content = "Tapi sekarang karena pesananmu sudah diantar, aku bisa menanganinya segera!",
  ui_story_5060_50600201_58_dialog_content = "Hah? Tiba-tiba banyak cahaya berwarna-warni muncul di depanku!",
  ui_story_5060_50600201_59_dialog_content = "Ini pasti Light Trail yang PlayerName bicarakan.",
  ui_story_5060_50600201_60_dialog_content = "Jika kamu mengikuti jejak cahaya tertentu, kamu bisa menghabisi musuh dalam sekejap!",
  ui_story_5060_50600201_61_dialog_content = "Begitu. Jadi itu hukum dari dunia ini?",
  ui_story_5060_50600201_62_dialog_content = "Ini seperti permainan, jadi seharusnya tidak terlalu sulit!",
  ui_story_5060_50600201_63_dialog_content = "Baiklah! Sekarang aku tahu aturannya, saatnya bermain!",
  ui_story_5060_50600201_64_dialog_content = "Tohru selalu sangat bersemangat saat harus menghancurkan musuh-musuhnya.",
  ui_story_5060_50600202_1_dialog_content = "Itu luar biasa, Nona Tohru! Tidak menyangka kamu menggunakan ekormu untuk mengalahkan Eclipsite!",
  ui_story_5060_50600202_2_dialog_content = "Jika Vice ada di sini, dia pasti ingin berteman denganmu!",
  ui_story_5060_50600202_3_dialog_content = "Mempertahankan sikap elegan dan tenang bahkan saat berperang adalah keterampilan dasar bagi setiap pelayan sejati!",
  ui_story_5060_50600202_4_dialog_content = "(Menendang Eclipsites ke udara dengan ekor... bisakah itu benar-benar dianggap \"anggun\"? Sepertinya dia bisa mengajari Vice satu atau dua hal...)",
  ui_story_5060_50600202_5_dialog_content = "Izinkan saya untuk menyampaikan rasa terima kasih saya sekali lagi. Kanna adalah anggota keluarga yang sangat berharga bagi saya.",
  ui_story_5060_50600202_6_dialog_content = "Aku sangat khawatir sejak kita terpisah. Terima kasih atas bantuan kalian berdua!",
  ui_story_5060_50600202_7_dialog_content = "Entahlah, apakah kita benar-benar pantas mendapatkan semua itu...",
  ui_story_5060_50600202_8_dialog_content = "Sebenarnya, kami tidak banyak melakukan sesuatu untuk Kanna. Kamu lah yang datang menyelamatkan situasi, Nona Tohru.",
  ui_story_5060_50600202_9_dialog_content = "Saya bisa melihat kalian berdua adalah orang baik, bukan? Tolong jangan khawatir, saya hanya ingin mengucapkan terima kasih!",
  ui_story_5060_50600202_10_dialog_content = "PlayerName dan Tessa adalah orang-orang yang baik.",
  ui_story_5060_50600202_11_dialog_content = "Mereka merawatku, memberiku permen, dan bahkan membantuku menemukan kamu.",
  ui_story_5060_50600202_12_dialog_content = "Tapi orang-orang lain itu jahat.",
  ui_story_5060_50600202_13_dialog_content = "Sebenarnya, Tessa dan saya sedang berada di lelang bawah tanah ketika kami bertemu dengan Kanna.",
  ui_story_5060_50600202_14_dialog_content = "Tempat itu bukanlah tempat yang tepat untuk anak kecil, jadi kami pergi untuk menanyakan tentang situasinya.",
  ui_story_5060_50600202_15_dialog_content = "Tapi tepat saat kami bersiap untuk mengawalnya pergi, segerombolan preman tiba-tiba muncul menghadang kami.",
  ui_story_5060_50600202_16_dialog_content = "Orang-orang brengsek itu menuduh kita mencuri harta yang akan mereka pajang, yang disebut \"<color=#FFB400>koleksi</color>.\"",
  ui_story_5060_50600202_17_dialog_content = "Dan begitulah kita semua berakhir di sini.",
  ui_story_5060_50600202_18_dialog_content = "Kanna, kamu benar-benar tidak memakan harta karun mereka?",
  ui_story_5060_50600202_19_dialog_content = "Tidak ada sama sekali.",
  ui_story_5060_50600202_20_dialog_content = "Tapi bau di dalam kotak harta itu sangat familier... Aku tak bisa menahan diri untuk menyentuhnya...",
  ui_story_5060_50600202_21_dialog_content = "Jangan merasa bersalah, Kanna! Orang-orang itu adalah sekumpulan orang bodoh yang jahat, tetapi kamu gadis yang baik!",
  ui_story_5060_50600202_22_dialog_content = "*Berpelukan, berpelukan* Tessa...",
  ui_story_5060_50600202_23_dialog_content = "Listrikmu... Terasa menyenangkan...",
  ui_story_5060_50600202_24_dialog_content = "Ah... Dia kembali bersandar di pelukanku.",
  ui_story_5060_50600202_25_dialog_content = "A-apa yang harus kulakukan?",
  ui_story_5060_50600202_26_dialog_content = "Maaf, dia biasanya tidak seperti ini! Lagipula, ini adalah dunia baru yang asing baginya, jadi wajar jika dia merasa sedikit bingung.",
  ui_story_5060_50600202_27_dialog_content = "Sekarang, Kanna, itu tidak sopan. Jika kamu butuh mana, kamu bisa makan sedikit dari milikku.",
  ui_story_5060_50600202_28_dialog_content = "Mana-mu rasanya tidak enak.",
  ui_story_5060_50600202_29_dialog_content = "Apa? Mana saya rasanya enak kok!",
  ui_story_5060_50600202_30_dialog_content = "Tohru... Kapan kita bisa pulang?",
  ui_story_5060_50600202_31_dialog_content = "Aku juga ingin pulang, tapi pertama-tama kita perlu menemukan tempat di mana mana cukup stabil untuk mengaktifkan portal.",
  ui_story_5060_50600202_32_dialog_content = "Aku sedih. Aku merindukan Saikawa.",
  ui_story_5060_50600202_33_dialog_content = "Jangan khawatir, aku yakin kita akan menemukan cara kembali ke dunia itu segera.",
  ui_story_5060_50600202_34_dialog_content = "Ngomong-ngomong, aku ingin bertanya tentang itu...",
  ui_story_5060_50600202_35_dialog_content = "Kamu sebutkan tadi, saat kita melawan Eclipsite barusan—Bahwa kalian berdua berasal dari dunia lain.",
  ui_story_5060_50600202_36_dialog_content = "Kamu nggak bercanda... 'kan?",
  ui_story_5060_50600202_37_dialog_content = "Meskipun benar bahwa penampilan kalian cukup mirip dengan yang kita kenal sebagai Aurorian demi-human...",
  ui_story_5060_50600202_38_dialog_content = "Aku belum pernah melihat siapa pun atau apa pun menyerap dan melepaskan energi dengan cara yang sama seperti yang kamu lakukan.",
  ui_story_5060_50600202_39_dialog_content = "Mungkin itu kasusmu, tapi kami memang naga dari dunia lain!",
  ui_story_5060_50600202_40_dialog_content = "Ini seperti manga-manga itu.",
  ui_story_5060_50600202_41_dialog_content = "Sayangnya, kita masih belum bisa terhubung kembali dengan sebagian besar anggota grup kita...",
  ui_story_5060_50600202_42_dialog_content = "Tokoh utama dalam manga ini sedang menghadapi masalah besar sekarang.",
  ui_story_5060_50600202_43_dialog_content = "Kamu terlalu banyak membaca manga, Kanna.",
  ui_story_5060_50600202_44_dialog_content = "Pertarungan selesai. Aku lelah.",
  ui_story_5060_50600202_45_dialog_content = "Apakah Anda terburu-buru, Nona Tohru?",
  ui_story_5060_50600202_46_dialog_content = "Saya memang... Tapi saya masih punya banyak waktu untuk mengirim pesanan berikutnya.",
  ui_story_5060_50600202_47_dialog_content = "Lalu, bisakah kamu ceritakan tentang duniamu sambil istirahat di sini?",
  ui_story_5060_50600202_48_dialog_content = "Sepertinya kamu sangat ingin tahu tentang kisah cinta antara Kobayashi dan diriku! Aku dengan senang hati akan menceritakan semuanya untukmu!",
  ui_story_5060_50600202_49_dialog_content = "Ceritanya panjang, jadi kamu harus siap mendengarnya!",
  ui_story_5060_50600202_50_dialog_content = "Tentu. Aku bisa makan siang sambil menunggumu, meskipun aku yakin makanannya sudah dingin sekarang...",
  ui_story_5060_50600202_51_dialog_content = "Ini tidak apa-apa! Hanya perlu sedikit panas saja!",
  ui_story_5060_50600202_52_dialog_content = "K-Kamu bisa bernapas api?! Itu langka, bahkan di dunia kita!",
  ui_story_5060_50600202_53_dialog_content = "Wow! Makanannya hangat lagi!",
  ui_story_5060_50600202_54_dialog_content = "Suhunya pas banget... Anda pasti memiliki kontrol yang sempurna atas nyala api Anda, Nona Tohru!",
  ui_story_5060_50600202_55_dialog_content = "Silakan menikmati makanan kalian sambil aku menghibur kalian semua dengan ceritaku!",
  ui_story_5060_50600202_56_dialog_content = "<color=#e8d9bb>Tohru dengan penuh semangat menceritakan kisah pertemuan dan keakrabannya dengan seorang gadis muda bernama Kobayashi.</color>",
  ui_story_5060_50600202_57_dialog_content = "<color=#e8d9bb>Namun, menurut Kanna, tampaknya Tohru telah memasukkan banyak imajinasi subjektifnya sendiri ke dalam cerita...</color>",
  ui_story_5060_50600202_58_dialog_content = "Ah, begitu.",
  ui_story_5060_50600202_59_dialog_content = "Dunia tanpa Eclipsite atau malam yang tak berujung, di mana semua orang hidup dalam damai dan tertib... Aku benar-benar ingin melihatnya dengan mataku sendiri.",
  ui_story_5060_50600202_60_dialog_content = "Sepertinya kamu juga sangat dekat dengan Miss Kobayashi, ya.",
  ui_story_5060_50600202_61_dialog_content = "Aku yakin dia akan sangat khawatir jika kamu tidak segera menemukan cara kembali ke dunianya.",
  ui_story_5060_50600202_62_dialog_content = "Benar, itulah mengapa aku memutuskan untuk bekerja sebagai pelayan pengantar!",
  ui_story_5060_50600202_63_dialog_content = "Dengan cara ini, saya bisa menghasilkan uang sambil mencari teman-teman yang hilang. Setelah semua orang berkumpul kembali, kita bisa fokus dalam mencari jalan pulang!",
  ui_story_5060_50600202_64_dialog_content = "Tunggu... Mungkin jika Kobayashi melihatku setelah menghilang selama tiga hari, dia mungkin... Heeheehee...",
  ui_story_5060_50600202_65_dialog_content = "Jangan berpikiran kotor, Tohru.",
  ui_story_5060_50600202_66_dialog_content = "Tapi, aku juga merindukan Kobayashi.",
  ui_story_5060_50600202_67_dialog_content = "Jadi, selain menemukan teman-temanmu, kamu juga perlu menemukan tempat khusus agar portal-mu bisa bekerja, benar?",
  ui_story_5060_50600202_68_dialog_content = "Kalau begitu, saya sarankan kamu pergi bersama PlayerName untuk bertemu dengan Cloudrover Guild.",
  ui_story_5060_50600202_69_dialog_content = "Salah satu pialang informasi paling profesional di seluruh Astra ada di sana. Dia mungkin bisa membantumu.",
  ui_story_5060_50600202_70_dialog_content = "Hah? Kamu tidak ikut, Tessa?",
  ui_story_5060_50600202_71_dialog_content = "Jangan lupa, kami di sini untuk pekerjaan pengawalan untuk lelang.",
  ui_story_5060_50600202_72_dialog_content = "Sekarang kita sudah selesai, salah satu dari kita harus melapor atau semua usaha kita sia-sia.",
  ui_story_5060_50600202_73_dialog_content = "Wow, bagaimana bisa hampir lupa... Aku mengandalkanmu nanti, Tessa!",
  ui_story_5060_50600202_74_dialog_content = "Ikuti saya, kalian berdua! Kebetulan saya cukup akrab dengan pemimpin Cloudrover Guild.",
  ui_story_5060_50600202_75_dialog_content = "Persekutuan Cloudrover... Nama itu terdengar familiar, tapi di mana saya pernah mendengarnya sebelumnya...?",
  ui_story_5060_50600202_76_dialog_content = "Eh?! Bukankah itu tempat pesanan selanjutnya harus diantarkan?!",
  ui_story_5060_50600202_77_dialog_content = "Dan alasan mengapa tidak diantarkan pada waktu sebelumnya...",
  ui_story_5060_50600202_78_dialog_content = "Karena penerimanya terlalu sibuk melawan sekelompok gangster!",
  ui_story_5060_50600301_1_dialog_content = "Apakah ini Persekutuan Cloudrover yang sama?!",
  ui_story_5060_50600301_2_dialog_content = "Biarkan aku melihat nama mereka sekali lagi... \"<color=#FFB400>Asisten yang Sangat Penting</color>\"?",
  ui_story_5060_50600301_3_dialog_content = "Nona Sheol, Nona Sheol! Apakah kamu di sini?",
  ui_story_5060_50600301_4_dialog_content = "Guild ini sangat sepi sekarang... Tunggu, apa ini?!",
  ui_story_5060_50600301_5_dialog_content = "Lemari arsip telah dipaksa terbuka. Dokumen intelijen dan tagihan-tagihan tersebar di lantai. Apakah mereka telah dirampok?",
  ui_story_5060_50600301_6_dialog_content = "Jika begitu, itu berarti pelanggan kita kemungkinan besar dalam masalah!",
  ui_story_5060_50600301_7_dialog_content = ". I'll designating  Parrish the thought of the day. I'm an expert on pound it! I in - fri, and I is a good idea and the pound. The result is a pound it! I am a student at. The a. The result is a pound it! I am a student. The result is a pound it! I am a student in the. The result is in. The result is a. The result is a pound. The result is a pound it! I a. The result is a pound it! on Casually. and the. The ID cards the. The result is a pound itencore. The result is a pound",
  ui_story_5060_50600301_8_dialog_content = "Tapi dulu, kau adalah yang terburuk dari yang terburuk.",
  ui_story_5060_50600301_9_dialog_content = "Sejujurnya, Kanna, jangan mengatakan hal-hal seperti itu! Itu tidak sopan!",
  ui_story_5060_50600301_10_dialog_content = "Hei, teman-teman, kalian di sini untuk bertemu bos kami, bukan?",
  ui_story_5060_50600301_11_dialog_content = "Saya khawatir bos kami sedang sibuk dengan pekerjaan akhir-akhir ini dan tidak bisa bertemu pengunjung secara langsung. Jika Anda memiliki pertanyaan, silakan bicarakan dengan asisten baru kami.",
  ui_story_5060_50600301_12_dialog_content = "Nona Sheol tidak ada di sini? Dan dia juga merekrut asisten baru?",
  ui_story_5060_50600301_13_dialog_content = "Apakah orang ini \"Asisten Sangat Penting\" yang memesan makanan ini?",
  ui_story_5060_50600301_14_dialog_content = "Jika dia ada, bisakah kamu beritahu dia bahwa pelayan pengantar restoran telah tiba dengan pesanannya?",
  ui_story_5060_50600301_15_dialog_content = "Selain itu, PlayerName dan saya juga ingin mengajukan beberapa pertanyaan kepada guild ini, jika itu diperbolehkan...",
  ui_story_5060_50600301_16_dialog_content = "Saya mengerti. Makanan bungkus ini dipesan oleh asisten dan yang lainnya khusus untuk bos kita, yang terlalu sibuk dengan pekerjaan.",
  ui_story_5060_50600301_17_dialog_content = "Sayangnya, guild kami saat ini sedang menghadapi masalah kecil. Saya khawatir kami tidak memiliki waktu untuk menikmati kelezatan restoran Anda saat ini.",
  ui_story_5060_50600301_18_dialog_content = "Aku akan menerima pesanan makanan untuk bos kita dan menyelesaikan tagihannya.",
  ui_story_5060_50600301_19_dialog_content = "Tahu tidak, saat ini guild sedang menangani...",
  ui_story_5060_50600301_20_dialog_content = "Kamu pasti PlayerName yang terkenal, partner Caelestite kami, bukan?",
  ui_story_5060_50600301_21_dialog_content = "Yang terkenal...",
  ui_story_5060_50600301_22_dialog_content = "Caelestite...?",
  ui_story_5060_50600301_23_dialog_content = "T-Tolong jangan panggil aku seperti itu! Kamu membuatku malu di depan teman-teman baruku!",
  ui_story_5060_50600301_24_dialog_content = "Saya mengerti. Maaf jika ini menyebabkan ketidaknyamanan.",
  ui_story_5060_50600301_25_dialog_content = "Kebetulan, kami memiliki beberapa urusan internal untuk dibahas dengan Anda, PlayerName. Apakah Anda keberatan bergabung dengan kami di luar?",
  ui_story_5060_50600301_26_dialog_content = "Kalian berdua, wanita cantik, silakan tunggu sebentar di ruang tamu.",
  ui_story_5060_50600301_27_dialog_content = "Aduh—Kita harus menunggu?",
  ui_story_5060_50600301_28_dialog_content = "Aku penasaran, apakah kalian berdua tertarik untuk menikmati menu spesial kami selama menunggu?",
  ui_story_5060_50600301_29_dialog_content = "Guild Cloudrover kami telah mengumpulkan berbagai harta karun eksotis dari Illumina Undercities, Gurun Rediesel, Northland Court, dan lainnya...",
  ui_story_5060_50600301_30_dialog_content = "Wah, banyak sekali yang lucu dan cantik—",
  ui_story_5060_50600301_31_dialog_content = "Jika kamu menemukan harta karun yang menarik perhatianmu, kami dengan senang hati akan menawarkannya dengan harga diskon, sebagai tanda persahabatan kita.",
  ui_story_5060_50600301_32_dialog_content = "Tapi saya tidak punya uang.",
  ui_story_5060_50600301_33_dialog_content = "Ahem! Kamu tahu, Kanna, aku sudah dibayar untuk pekerjaanku. Tidak ada salahnya menghabiskan sedikit dari itu...",
  ui_story_5060_50600301_34_dialog_content = "Benarkah? Kamu yang terbaik, Tohru!",
  ui_story_5060_50600301_35_dialog_content = "Jadi apa yang sebenarnya terjadi pada guild itu? Sepertinya cukup serius.",
  ui_story_5060_50600301_36_dialog_content = "Apakah kamu baru saja mendengar tentang lelang bawah tanah yang heboh di Umbraton dan Lower Lumopolis?",
  ui_story_5060_50600301_37_dialog_content = "Sebagai salah satu guild terkenal di Astra, Cloudrover Guild kami juga merupakan sponsor besar untuk lelang ini.",
  ui_story_5060_50600301_38_dialog_content = "Tapi belakangan ini, keadaan di lelang menjadi kacau, dengan orang-orang bersikeras bahwa barang yang dipamerkan mereka ternyata dicuri.",
  ui_story_5060_50600301_39_dialog_content = "Mereka membuat tuduhan tanpa dasar dan berkelahi dengan peserta lain, menyebabkan kekacauan total.",
  ui_story_5060_50600301_40_dialog_content = "Lady Sheol sedang bekerja keras untuk menyelesaikan masalah ini.",
  ui_story_5060_50600301_41_dialog_content = "Oh... itu...",
  ui_story_5060_50600301_42_dialog_content = "Pengacau-pengacau itu bahkan menerobos masuk ke Guild kami, menyebabkan keributan yang baru saja kalian saksikan.",
  ui_story_5060_50600301_43_dialog_content = "Kami sudah berusaha keras mengangkut barang-barang lelang, dan sekarang mereka menghilang. Bukankah kamu, Cloudrover Guild, harus bertanggung jawab?",
  ui_story_5060_50600301_44_dialog_content = "Koleksi itu dicuri saat kamu bertugas, jadi kamu harus membayarnya!",
  ui_story_5060_50600301_45_dialog_content = "Kalau tidak, tuan Lumopolis yang mempekerjakan kami tidak akan mengampunimu!",
  ui_story_5060_50600301_46_dialog_content = "Benar. Saya sarankan semua anggota dari Cloudrover Guild bekerja sama dengan penyelidikan kami dan jangan melawan tuan kami.",
  ui_story_5060_50600301_47_dialog_content = "Jadi bahkan prajurit pribadi yang bekerja untuk bangsawan Lumopolis juga terlibat dalam hal itu, ya? Sungguh menjijikkan.",
  ui_story_5060_50600301_48_dialog_content = "Koleksi langka seringkali dipesan lebih dulu oleh bangsawan berpengaruh; itu merupakan rutinitas yang umum.",
  ui_story_5060_50600301_49_dialog_content = "Bagi mereka, mengajukan penawaran hanyalah cara untuk menunjukkan kekuatan dan status mereka.",
  ui_story_5060_50600301_50_dialog_content = "Namun, apa yang mungkin sedikit mengganggu mereka akan menjadi beban yang nyata bagi kita para pedagang.",
  ui_story_5060_50600301_51_dialog_content = "Jika bukan karena kecerdikan bos yang membawa asisten yang mampu untuk menangani mereka, kita pasti akan kewalahan.",
  ui_story_5060_50600301_52_dialog_content = "Jadi bagaimana Nona Sheol berencana untuk mengatasi ini?",
  ui_story_5060_50600301_53_dialog_content = "Dia mencurigai bahwa barang-barang ini menghilang dari peti jauh sebelum sampai di lokasi lelang.",
  ui_story_5060_50600301_54_dialog_content = "Itulah mengapa dia berharap kamu, yang memiliki ikatan dekat dengannya, bisa membantu dalam masalah ini.",
  ui_story_5060_50600301_55_dialog_content = "Coba gunakan kemampuan psikis Caelestite-mu untuk melihat apakah kamu bisa menemukan petunjuk tentang barang yang hilang dan mengkonfirmasi kecurigaannya.",
  ui_story_5060_50600301_56_dialog_content = "...Maka maaf, aku terpaksa membuat kalian semua kecewa...",
  ui_story_5060_50600301_57_dialog_content = "Sebenarnya, aku salah satu tamu yang sempat diganggu di pelelangan tadi...",
  ui_story_5060_50600301_58_dialog_content = "Untuk menjernihkan suasana, saya mencoba menggunakan kemampuan psikis saya untuk mencari petunjuk, tetapi saya tidak menemukan apa-apa.",
  ui_story_5060_50600301_59_dialog_content = "Saya khawatir peti yang berisi koleksi ini memang benar-benar kosong!",
  ui_story_5060_50600301_60_dialog_content = "Sayang sekali. Sepertinya kita harus mengandalkan asisten untuk menjaga orang-orang itu sibuk.",
  ui_story_5060_50600301_61_dialog_content = "Jika Anda bisa membantu kami menyelesaikan ini, bos kami pasti akan mengungkapkan rasa terima kasihnya.",
  ui_story_5060_50600301_62_dialog_content = "Rasa terima kasih dari Sheol, ya...",
  ui_story_5060_50600301_63_dialog_content = "Kamu sangat membantu saya, temanku...",
  ui_story_5060_50600301_64_dialog_content = "Sepertinya aku perlu meningkatkan penilaianku terhadapmu satu atau dua tingkat.",
  ui_story_5060_50600301_65_dialog_content = "Sekarang ceritakan padaku, bagaimana cara yang tepat untuk mengkompensasi kamu atas kesulitan yang kamu alami...?",
  ui_story_5060_50600301_66_dialog_content = "...A-Aku tidak keberatan membantu, tapi aku akan melewatkan ucapan terima kasih dari Lady Sheol! Aku benar-benar tidak bisa menangani lebih dari itu lagi!!",
  ui_story_5060_50600301_67_dialog_content = "Hmm, kayaknya aku lewat deh.",
  ui_story_5060_50600301_68_dialog_content = "Hah? Suara siapa itu?",
  ui_story_5060_50600301_69_dialog_content = "Asisten <color=#FFB400>Lucoa</color>!",
  ui_story_5060_50600301_70_dialog_content = "(Tunggu, wanita super-matang ini adalah asisten yang kita bicarakan sebelumnya?!)",
  ui_story_5060_50600301_71_dialog_content = "(Dia memang memiliki aura yang mirip dengan Lady Sheol... Tapi sepertinya dia lebih ramah.)",
  ui_story_5060_50600301_72_dialog_content = "Oh, kamu di sini juga? Aku benar-benar minta maaf, tapi aku masih punya pekerjaan yang harus dikerjakan, tahu!",
  ui_story_5060_50600301_73_dialog_content = "Preman-preman itu benar-benar berdedikasi pada pekerjaan mereka. Aku sudah berusaha sebaik mungkin untuk membujuk mereka, tapi mereka tetap tidak mau mengalah...",
  ui_story_5060_50600301_74_dialog_content = "Hai, teman-teman, waspadalah. Gadis ini bukan Aurorian biasa... Ada sesuatu yang sangat aneh tentang dia!!",
  ui_story_5060_50600301_75_dialog_content = "Saya tahu saya terlihat sedikit berbeda, tapi itu bukan alasan untuk berhati-hati sekali!",
  ui_story_5060_50600301_76_dialog_content = "Saya lebih dari senang untuk membahas dan menemukan solusi untuk masalah ini!",
  ui_story_5060_50600301_77_dialog_content = "Jangan tertipu oleh penampilannya! Hmph, dia pikir dia bisa membujuk kita dengan kata-kata manis, dan kita akan pergi begitu saja? Tidak semudah itu!",
  ui_story_5060_50600301_78_dialog_content = "Pada akhirnya, dia hanya seorang gadis setengah manusia, bahkan tidak layak menjadi pelayan bagi tuan-tuan di uptown.",
  ui_story_5060_50600301_79_dialog_content = "Ayo kita mengeroyoknya, semuanya. Pasti kita bisa mengalahkannya dan kemudian gunakan dia sebagai alat tawar-menawar!",
  ui_story_5060_50600301_80_dialog_content = "Oh? Betapa menakutkannya!",
  ui_story_5060_50600301_81_dialog_content = "Tinggalkan dia sendiri, kalian bajingan busuk—",
  ui_story_5060_50600301_82_dialog_content = "Oh, seorang ksatri., se,, a real, seorang ksatria datang meny 100% Sga seperti yang  to the 100%, 1.",
  ui_story_5060_50600301_83_dialog_content = "Tapi sebagai <color=#FFB400>Asisten Penting</color> di Guild, aku juga cukup berguna dalam pertempuran.",
  ui_story_5060_50600302_1_dialog_content = "Mereka terus berdatangan... Apakah kamu baik-baik saja, Nona Lucoa?",
  ui_story_5060_50600302_2_dialog_content = "Aku baik-baik saja! Justru pasti sulit bagimu untuk mendukungku sambil melindungi dirimu sendiri, PlayerName.",
  ui_story_5060_50600302_3_dialog_content = "T-Tunggu, darimana kamu tahu namaku?",
  ui_story_5060_50600302_4_dialog_content = "Dari Lady Sheol, tentu saja! Dia banyak bercerita tentang kamu...",
  ui_story_5060_50600302_5_dialog_content = "Kutukan! Pekerjaan para tuan belum selesai. Bangkitlah—jangan berani meremehkan kami!",
  ui_story_5060_50600302_6_dialog_content = "Aku berharap kalian semua bisa membaca situasi dan bertindak secara tepat.",
  ui_story_5060_50600302_7_dialog_content = "Kalian semua benar-benar melampaui batas... Yang berarti aku harus lebih serius menghadapinya... Anak-anak baik, ingat untuk memalingkan pandangan!",
  ui_story_5060_50600302_8_dialog_content = "H-Hei! Kenapa kau menutupi mataku?",
  ui_story_5060_50600302_9_dialog_content = "Apa?... I-i-ini makhluk apa?! Ugh...",
  ui_story_5060_50600302_10_dialog_content = "Fiuh... Kamu bisa lihat sekarang. Orang-orang ini seharusnya sedikit lebih tenang sekarang.",
  ui_story_5060_50600302_11_dialog_content = "(Hah? Wah... Apa yang baru saja Lucoa lakukan pada preman-preman itu..?)",
  ui_story_5060_50600302_12_dialog_content = "(Mereka terlihat seperti baru saja dilempar ke dalam lubang penuh Eclipsite tingkat tinggi...)",
  ui_story_5060_50600302_13_dialog_content = "Biar aku merasakan sekitar...",
  ui_story_5060_50600302_14_dialog_content = "Apakah ini... Sebuah bulu...?",
  ui_story_5060_50600302_15_dialog_content = "Ah—Aku bilang jangan mengintip!",
  ui_story_5060_50600302_16_dialog_content = "M-Maaf! Aku hanya penasaran tentang kekuatanmu, itu saja...",
  ui_story_5060_50600302_17_dialog_content = "Oh? Jadi kamu penasaran ingin melihat wujud asliku?",
  ui_story_5060_50600302_18_dialog_content = "Tahu tidak, kamu sama imutnya dengan <color=#FFB400>Shouta</color> jika aku perhatikan lebih dekat!",
  ui_story_5060_50600302_19_dialog_content = "Wajahmu saat menggunakan kekuatan sangat imut. Jadi ini Caelestite yang sering kudengar!",
  ui_story_5060_50600302_20_dialog_content = "Wajah yang sangat imut... Apakah kamu keberatan jika aku menyentuhnya?",
  ui_story_5060_50600302_21_option_content = "Enyahlah, iblis!",
  ui_story_5060_50600302_22_dialog_content = "Aduh, sakit banget. Aku sama sekali bukan iblis...",
  ui_story_5060_50600302_23_dialog_content = "Sekarang aku orang baik!",
  ui_story_5060_50600302_24_dialog_content = "Orang lain mungkin sudah melaporkanmu ke Lumopolis Guardian sejak lama!!",
  ui_story_5060_50600302_25_option_content = "T-Tapi aku akan tercekik...",
  ui_story_5060_50600302_26_dialog_content = "A-Apakah kamu tidak punya urusan guild lain yang harus diurus, Miss Lucoa...?",
  ui_story_5060_50600302_27_dialog_content = "Tempat ini memang berbahaya. Siapa tahu kapan prajurit pribadi itu akan muncul untuk menyelidiki... Hahaha...",
  ui_story_5060_50600302_28_dialog_content = "Sejujurnya, saya lebih merupakan pengawal daripada asisten yang dipekerjakan oleh Lady Sheol untuk urusan ini.",
  ui_story_5060_50600302_29_dialog_content = "Sebenarnya, aku cukup kuat dan bisa menangani kebanyakan situasi.",
  ui_story_5060_50600302_30_dialog_content = "Lagi pula, kebetulan di tanah kelahiranku, aku adalah seorang dewi...",
  ui_story_5060_50600302_31_dialog_content = "Lu—co—a—",
  ui_story_5060_50600302_32_dialog_content = "Hmm? Apakah itu kamu, Tohru?",
  ui_story_5060_50600302_33_dialog_content = "Aku telah kelelahan mencoba mencari cara untuk mengaktifkan kembali portal ini...",
  ui_story_5060_50600302_34_dialog_content = "Tapi kenapa kamu malah bermalas-malasan di sini?!",
  ui_story_5060_50600302_35_dialog_content = "Dan menyebut diri Anda sebagai \"Asisten Sangat Penting\"...",
  ui_story_5060_50600302_36_dialog_content = "Astaga! Bagaimana kamu bisa menemukan nama samaranku di dunia ini, Tohru...?",
  ui_story_5060_50600302_37_dialog_content = "Lucoa telah terbongkar.",
  ui_story_5060_50600302_38_dialog_content = "Ah! Jangan bilang kamu yang mengantarkan makananku, Tohru?",
  ui_story_5060_50600302_39_dialog_content = "Seorang pelayan pengantar barang... Gimmick yang menarik!",
  ui_story_5060_50600302_40_dialog_content = "Sejak saya menyadari betapa berbedanya mana di dunia ini, saya telah mencoba mencari cara untuk meningkatkan kemampuan tubuh saya dalam mengkonversinya.",
  ui_story_5060_50600302_41_dialog_content = "Dengan begitu, aku bisa menggunakan kekuatanku untuk menentukan lokasi persis semua orang.",
  ui_story_5060_50600302_42_dialog_content = "Sayangnya, karena kebanyakan orang di sini cenderung menggunakan \"Luminatics\" yang disebut-sebut ini untuk mengatasi masalah mereka...",
  ui_story_5060_50600302_43_dialog_content = "Aku belum bisa menemukan anak yang berbakat setara dengan Shouta untuk membentuk pakta sementara denganku.",
  ui_story_5060_50600302_44_dialog_content = "Syukurlah sejauh ini tidak ada yang terluka.",
  ui_story_5060_50600302_45_dialog_content = "Tapi aku tidak bisa bilang aku tidak tertarik dengan Caelestite yang selalu dibicarakan orang ini! Justru, aku punya harapan besar padanya!",
  ui_story_5060_50600302_46_dialog_content = "Sudahi saja, Lucoa!",
  ui_story_5060_50600302_47_dialog_content = "Ahem! Pokoknya, kita berhasil menemukan Lucoa, yang berarti sekarang kita hanya perlu menemukan Elma dan Fafnir.",
  ui_story_5060_50600302_48_dialog_content = "Nah, Lucoa? Semua orang bilang guild ini adalah salah satu sumber informasi terbaik.",
  ui_story_5060_50600302_49_dialog_content = "Apa kamu menemukan sesuatu tentang mereka berdua?",
  ui_story_5060_50600302_50_dialog_content = "Saya telah memperhatikan dengan seksama segala hal yang berkaitan dengan naga atau setengah manusia dengan karakteristik mirip naga.",
  ui_story_5060_50600302_51_dialog_content = "Petunjuk terbaru yang aku kerjakan saat ini melibatkan hilangnya sebuah koleksi dari lelang.",
  ui_story_5060_50600302_52_dialog_content = "Hah? Jadi kamu juga menyelidiki para bandit itu? Dan itu karena mereka ada hubungannya dengan naga?",
  ui_story_5060_50600302_53_dialog_content = "Tahu 1, lo t stumpedia dave and busters Moss on 2.0",
  ui_story_5060_50600302_54_dialog_content = "Lucoa mulai serius.",
  ui_story_5060_50600302_55_dialog_content = "Kebanyakan preman itu bekerja untuk geng penyelundup, dan salah satu dari mereka secara tidak sengaja menyebutkan bahwa barang yang hilang adalah harta karun tersembunyi naga.",
  ui_story_5060_50600302_56_dialog_content = "Sebuah harta karun yang hanya diperoleh setelah menghadapi bahaya kematian di bawah cakar naga.",
  ui_story_5060_50600302_57_dialog_content = "Apakah salah satu dari kita menjatuhkan sesuatu? Mungkin Fafnir...?",
  ui_story_5060_50600302_58_dialog_content = "Mungkin tidak...",
  ui_story_5060_50600302_59_dialog_content = "Jika tidak, mereka akan dikutuk.",
  ui_story_5060_50600302_60_dialog_content = "Kau benar.",
  ui_story_5060_50600302_61_dialog_content = "Nona Lucoa, bolehkah aku menanyakan beberapa hal, jika tidak keberatan?",
  ui_story_5060_50600302_62_dialog_content = "Lady Sheol ingin menggunakan kekuatanku untuk mencari koleksi yang hilang.",
  ui_story_5060_50600302_63_dialog_content = "Tapi ketika saya mencoba menggunakannya di lelang, saya tidak tahu apakah itu karena kurang informasi atau sesuatu yang lain...",
  ui_story_5060_50600302_64_dialog_content = "Kekuatan psikisku tidak berhasil.",
  ui_story_5060_50600302_65_dialog_content = "Bisakah kamu beri tahu saya lebih banyak tentang koleksi yang hilang ini? Atau mungkin informasi lebih lanjut tentang geng penyelundup ini?",
  ui_story_5060_50600302_66_dialog_content = "Aku tahu apa yang kamu pikirkan. Sebagai seorang Caelestite, kamu perlu cukup familiar dengan sesuatu agar bisa merasakannya dengan kekuatanmu, kan?",
  ui_story_5060_50600302_67_dialog_content = "Para penyelundup yang dimaksud umumnya bekerja untuk kelas atas di Umbraton dan Lumopolis. Mereka mengkhususkan diri dalam memburu makhluk besar dan menggali reruntuhan untuk mencari artefak.",
  ui_story_5060_50600302_68_dialog_content = "Barang yang mereka bawa untuk dipamerkan kali ini sebagian besar adalah spesimen dan kulit dari makhluk langka dan berharga.",
  ui_story_5060_50600302_69_dialog_content = "Mereka mungkin bahkan membawa spesimen hidup...",
  ui_story_5060_50600302_70_dialog_content = "Itu menjelaskan mengapa bagian atas kotak itu terasa sangat hangat...",
  ui_story_5060_50600302_71_dialog_content = "Tunggu, apakah kamu juga menemukan petunjuk, Kanna?!",
  ui_story_5060_50600302_72_dialog_content = "Nah, Kanna? Bagaimana harta itu bisa hilang?",
  ui_story_5060_50600302_73_dialog_content = "Mungkin... Mungkin karena dia tumbuh kaki dan lari!",
  ui_story_5060_50600302_74_dialog_content = "Eh…",
  ui_story_5060_50600302_75_dialog_content = "Selain manga, aku bertanya-tanya apakah aku membiarkan kamu membaca terlalu banyak dongeng juga...",
  ui_story_5060_50600302_76_dialog_content = "...Masih belum ada hasil. Bahkan dengan bantuan Kanna dan Lucoa, serta mengetahui bahwa itu adalah spesimen hidup...",
  ui_story_5060_50600302_77_dialog_content = "Aku masih tidak bisa merasakan di mana lokasinya.",
  ui_story_5060_50600302_78_dialog_content = "Jangan frustrasi, PlayerName. Kau sudah melakukan banyak hal.",
  ui_story_5060_50600302_79_dialog_content = "Aku tahu, tapi tidak setiap hari aku bisa membantu semua orang sambil juga mendapatkan dukungan dari Lady Sheol. Aku berharap aku bisa melakukan lebih banyak...",
  ui_story_5060_50600302_80_dialog_content = "Ini datang kesempatanku.",
  ui_story_5060_50600302_81_dialog_content = "Ayo ke sini, Caelestite kecil! Mari berpelukan!",
  ui_story_5060_50600302_82_dialog_content = "Waaaah! L-L-Lepaskan...!",
  ui_story_5060_50600302_83_dialog_content = "Reaksi yang biasa saja, PlayerName.",
  ui_story_5060_50600302_84_dialog_content = "Terima kasih atas pengaruhmu, saya memiliki pemahaman yang lebih komprehensif tentang dunia ini. Dalam beberapa hal, rasanya seperti kita memiliki pikiran yang sama meskipun memiliki tubuh yang terpisah.",
  ui_story_5060_50600302_85_dialog_content = "Biarkan aku menularkan kekuatanku padamu!",
  ui_story_5060_50600302_86_dialog_content = "T-Tadi itu hanya aku menggunakan kemampuan psikisku! Aku hanya membantumu melihat jejak cahaya!",
  ui_story_5060_50600302_87_dialog_content = "Berhenti, atau aku akan melaporkanmu ke Nona Sheol!",
  ui_story_5060_50600302_88_dialog_content = "Benarkah? Saya dan Lady Sheol cukup dekat lho, tahu? Dia bahkan memberi saya sesuatu yang sangat saya inginkan sebagai uang muka gaji saya!",
  ui_story_5060_50600302_89_dialog_content = "Sayangnya, karena saya telah diberi penghormatan, saya tidak bisa lagi bertindak sesuka hati.",
  ui_story_5060_50600302_90_dialog_content = "Cepat Tohru, atau PlayerName mungkin akan mati...",
  ui_story_5060_50600302_91_dialog_content = "Ugh, jujur saja... Kau masih terlihat melakukan apa pun yang kau inginkan, Lucoa.",
  ui_story_5060_50600302_92_dialog_content = "Jika kamu punya banyak waktu luang seperti ini, kenapa tidak membantu saya mengirim pesanan-pesanan ini?!",
  ui_story_5060_50600302_93_dialog_content = "Pokoknya, PlayerName, kamu yakin mau membantu kami?",
  ui_story_5060_50600302_94_dialog_content = "Kamu tidak punya pekerjaan atau penyelidikan lain yang harus dilakukan?",
  ui_story_5060_50600302_95_dialog_content = "Bisa pergi bersama?",
  ui_story_5060_50600302_96_dialog_content = "Jangan mengatakan hal seperti itu, Kanna. PlayerName kebetulan adalah seseorang yang sangat penting di dunia ini.",
  ui_story_5060_50600302_97_dialog_content = "Saya yakin dia memiliki banyak hal yang sama pentingnya untuk dikerjakan sekarang.",
  ui_story_5060_50600302_98_dialog_content = "Sebenarnya, aku tidak tahu... Dan aku juga tidak terlalu penting, Nona Tohru. Ngomong-ngomong, ke mana pesanan selanjutnya?",
  ui_story_5060_50600302_99_dialog_content = "Biarkan saya melihat, sepertinya itu adalah pos di suatu tempat yang disebut \"Pos Illumina.\"",
  ui_story_5060_50600302_100_dialog_content = "Kalau begitu, tidak masalah! Aku juga perlu ke sana!",
  ui_story_5060_50600302_101_dialog_content = "Sebagai pos di perbatasan, pasti banyak penyelundup yang beroperasi di area ini. Saya yakin kita akan menemukan banyak informasi di sana!",
  ui_story_5060_50600302_102_dialog_content = "Yay, kita bisa pergi dalam petualangan lain!",
  ui_story_5060_50600302_103_dialog_content = "Untuk menghemat waktu, kenapa kita tidak terbang ke sana saja?",
  ui_story_5060_50600302_104_dialog_content = "Hah? Bagaimana kamu tahu aku bisa berubah menjadi naga, PlayerName? Aku tidak ingat pernah memberitahumu itu.",
  ui_story_5060_50600302_105_dialog_content = "Hah?",
  ui_story_5060_50600302_106_dialog_content = "Maksud saya, kita bisa naik Soroz ke Pos Illumina. Anda sedang membahas apa, Nona Tohru?",
  ui_story_5060_50600302_107_dialog_content = "S... Sor-apa?",
  ui_story_5060_50600401_1_dialog_content = "Jadi ini Soroz, PlayerName? Temanmu sangat kecil...",
  ui_story_5060_50600401_2_dialog_content = "Hei! Soroz akan sangat kesal jika kamu menganggapnya sebagai kapal udara biasa!",
  ui_story_5060_50600401_3_dialog_content = "Kamu akan mengerti begitu sampai di sana... Aku yakin Soroz tidak lebih kecil dari naga-naga yang sudah kamu sebutkan sejauh ini.",
  ui_story_5060_50600401_4_dialog_content = "Benarkah? Saya jadi semakin bersemangat untuk melihatnya!",
  ui_story_5060_50600401_5_dialog_content = "Namun, kapal udara ini terlalu kecil untuk mengangkut kita semua ke Soroz dalam satu perjalanan.",
  ui_story_5060_50600401_6_dialog_content = "Kamu bilang sesuatu tentang bisa terbang, 'kan, Nona Tohru?",
  ui_story_5060_50600401_7_dialog_content = "Tentu saja! Lagi pula, saya kan naga!",
  ui_story_5060_50600401_8_dialog_content = "Jadi kamu benar-benar bisa terbang?",
  ui_story_5060_50600401_9_dialog_content = "Aku ingin naik pesawat. Sepertinya menyenangkan.",
  ui_story_5060_50600401_10_dialog_content = "Kalau begitu, aku akan tetap bersama Kanna.",
  ui_story_5060_50600401_11_dialog_content = "Bisakah kamu mencoba menurunkan sedikit berat badan, Lucoa? Tidak ada ruang untuk sepeda motorku...",
  ui_story_5060_50600401_12_dialog_content = "Hei PlayerName, bolehkah saya mengajukan pertanyaan?",
  ui_story_5060_50600401_13_dialog_content = "Tentu, apa itu?",
  ui_story_5060_50600401_14_dialog_content = "Apa sebenarnya demi-human Aurorian itu?",
  ui_story_5060_50600401_15_dialog_content = "Saat saya mengantar paket, saya melihat beberapa anak bersayap terbang di langit.",
  ui_story_5060_50600401_16_dialog_content = "Mereka tampak begitu nyaman dan bebas, dan mereka terlihat sangat mirip dengan kita saat ini.",
  ui_story_5060_50600401_17_dialog_content = "Tapi, orang-orang Lumopolis sepertinya menganggap tanduk dan sayap mereka sebagai hal yang buruk... Meskipun saya tidak begitu mengerti mengapa.",
  ui_story_5060_50600401_18_dialog_content = "Apakah para bangsawan juga mengganggumu saat kau berada di Lumopolis, Nona Tohru?",
  ui_story_5060_50600401_19_dialog_content = "Sama sekali tidak. Mungkin karena aura destruktifku; tidak ada satupun dari mereka yang berani mendekatiku.",
  ui_story_5060_50600401_20_dialog_content = "Namun, mereka membuat hal-hal menjadi sangat sulit bagi demi-manusia lain yang bekerja di restoran milik Pak Liu. Aku tidak tahan melihat mereka.",
  ui_story_5060_50600401_21_dialog_content = "Ada banyak alasan yang terlibat, tetapi ras dan status mereka pasti merupakan faktor terbesar.",
  ui_story_5060_50600401_22_dialog_content = "Demi-human sejati tidak mampu menggunakan Luminatics, jadi mereka telah punah sejak lama.",
  ui_story_5060_50600401_23_dialog_content = "Demi-human Aurorian yang kita lihat saat ini adalah keturunan dari demi-human sejati yang menikah dengan Aurorian.",
  ui_story_5060_50600401_24_dialog_content = "Bagi Bangsawan Lumo, orang-orang yang tidak diinginkan ini tidak lebih dari noda bagi keyakinan mereka dan garis keturunan bangsawan mereka.",
  ui_story_5060_50600401_25_dialog_content = "Ugh, tidak lagi. Iman, garis keturunan murni, berkat... Karena pemikiran seperti ini, kita melihat manusia sebagai spesies yang bodoh dan rendah.",
  ui_story_5060_50600401_26_dialog_content = "Terima kasih, saat ini Aurorian semakin menerima Aurorian demi-human. Tren ini juga terjadi di kalangan beberapa bangsawan Lumopolis...",
  ui_story_5060_50600401_27_dialog_content = "Oh, sepertinya kita hampir sampai. Kita seharusnya bisa melihat Soroz setelah kita melewati awan-awan ini.",
  ui_story_5060_50600401_28_dialog_content = "Semua orang, perkenalkan teman saya Soroz!",
  ui_story_5060_50600401_29_dialog_content = "Orang Aurorian di dunia ini menyebut jenis mereka sebagai Colossi. Mereka adalah teman dekat Caelestite, dan hanya bisa dipiloti oleh orang-orang kami.",
  ui_story_5060_50600401_30_dialog_content = "Wow, ini sangat besar! Tunggu, apakah Soroz... Sebuah naga mekanik sepenuhnya?!",
  ui_story_5060_50600401_31_dialog_content = "Seekor naga robot, seperti di film-film.",
  ui_story_5060_50600401_32_dialog_content = "Sesuatu yang unik seperti ini pasti sangat hebat dalam bertempur, kan? Bisakah aku menantangnya bertarung sekarang juga?!",
  ui_story_5060_50600401_33_dialog_content = "Uh... Soroz belum pernah terlibat dalam pertempuran...",
  ui_story_5060_50600401_34_dialog_content = "Sayang sekali.",
  ui_story_5060_50600401_35_dialog_content = "Pokoknya, ayo masuk saja.",
  ui_story_5060_50600401_36_dialog_content = "Wah—Cantik sekali!",
  ui_story_5060_50600401_37_dialog_content = "Tempat ini, juga—",
  ui_story_5060_50600401_38_dialog_content = "Jangan ganggu orang lain, Kanna!",
  ui_story_5060_50600401_39_dialog_content = "Tidak hanya luas, tetapi juga dilengkapi dengan perabotan yang menarik. Tinggal di sini pasti sangat nyaman!",
  ui_story_5060_50600401_40_dialog_content = "Peringatan: mendekati batas berat. Harap hindari membawa bagasi berlebih.",
  ui_story_5060_50600401_41_dialog_content = "...Bukankah sudah kubilang, Lucoa? Kamu benar-benar harus mencoba menurunkan berat badan.",
  ui_story_5060_50600401_42_dialog_content = "Benarkah? Maksudmu bukan ekor gemukmu yang membuat kita terbebani?",
  ui_story_5060_50600401_43_dialog_content = "Jangan khawatir, mungkin hanya gangguan dalam sistem. Soroz jauh lebih tangguh dari itu.",
  ui_story_5060_50600401_44_dialog_content = "Sepertinya kamu sangat percaya pada Colossus besar ini. Kamu pasti memiliki hubungan yang indah dengannya.",
  ui_story_5060_50600401_45_dialog_content = "Yep! Lagipula, Soroz adalah salah satu teman terdekat dan terpentingku.",
  ui_story_5060_50600401_46_dialog_content = "Lebih dari sepuluh tahun yang lalu... Aku kehilangan rumahku, begitu juga seluruh keluargaku.",
  ui_story_5060_50600401_47_dialog_content = "Tak ada pilihan lain selain menerima bahwa aku adalah Caelestite terakhir yang hidup di dunia ini.",
  ui_story_5060_50600401_48_dialog_content = "Jika bukan karena Soroz yang menemani dan mengajari saya berbagai hal, saya tidak akan berada di posisi saya sekarang ini.",
  ui_story_5060_50600401_49_dialog_content = "Aku sangat paham.",
  ui_story_5060_50600401_50_dialog_content = "Hubungan saya dengan Kobayashi juga persis sama. Seperti yang diharapkan, cinta tidak mengenal batasan, bahkan antar spesies!",
  ui_story_5060_50600401_51_dialog_content = "A-Aku tidak yakin jika itu PERSIS sama.",
  ui_story_5060_50600401_52_dialog_content = "Jadi, Nona Tohru, aku tahu rasanya tiba di dunia baru yang asing, dan ketakutan serta ketidakpercayaan yang menyertainya.",
  ui_story_5060_50600401_53_dialog_content = "Tapi berkat bantuan Soroz, serta bantuan dari banyak teman...",
  ui_story_5060_50600401_54_dialog_content = "of  1  on the.",
  ui_story_5060_50600401_55_dialog_content = "Jadi ketika aku melihat betapa sangat kamu ingin bertemu kembali dengan teman-temanmu, hatiku mengatakan untuk membantumu dengan cara apa pun yang bisa aku lakukan.",
  ui_story_5060_50600401_56_dialog_content = "Teman adalah harta terbesar kita. Aku tidak tahu berapa lama lagi dunia kita akan terhubung...",
  ui_story_5060_50600401_57_dialog_content = "Tapi meskipun hanya untuk waktu yang singkat, aku benar-benar berharap kita semua bisa menjadi teman, Nona Tohru!",
  ui_story_5060_50600401_58_dialog_content = "Saya ingin mendengar lebih banyak cerita tentang dunia-dunia lain yang pernah Anda kunjungi... Serta kisah cinta antara Anda dan Miss Kobayashi!",
  ui_story_5060_50600401_59_dialog_content = "Sejujurnya, berani-beraninya kamu mengatakan semua itu...",
  ui_story_5060_50600401_60_dialog_content = "Bukankah sudah jelas bahwa kita sudah berteman?",
  ui_story_5060_50600401_61_dialog_content = "Ketika saya mengaktifkan Gerbang Teleportasi Dunia, awalnya saya bermaksud untuk kembali ke dunia asal saya dan mengambil beberapa foto dari sana...",
  ui_story_5060_50600401_62_dialog_content = "Tapi tahu nggak? Menurutku, pemandangan di dunia ini juga bagus lho!",
  ui_story_5060_50600401_63_dialog_content = "Setelah semua ini berakhir, yuk gunakan kamera ini untuk foto grup, oke?",
  ui_story_5060_50600401_64_dialog_content = "...Ya! Aku suka itu!",
  ui_story_5060_50600401_65_dialog_content = "Kamu tampak bahagia, PlayerName.",
  ui_story_5060_50600401_66_dialog_content = "Ingat untuk tersenyum seperti itu saat berfoto.",
  ui_story_5060_50600401_67_dialog_content = "Hahaha! Tentu saja!",
  ui_story_5060_50600401_68_dialog_content = "<color=#e8d9bb>Beberapa waktu kemudian...</color>",
  ui_story_5060_50600401_69_dialog_content = "Kita semakin dekat dengan alamat pengiriman.",
  ui_story_5060_50600401_70_dialog_content = "Apa sebenarnya tujuan membangun Pos Luar Illumina, PlayerName? Apakah ini semacam struktur pertahanan?",
  ui_story_5060_50600401_71_dialog_content = "Kurasa bisa dibilang begitu.",
  ui_story_5060_50600401_72_dialog_content = "Huh, Federasi Illumina benar-benar perlu merevisi kebijakan makan mereka jika para prajurit harus memesan makanan untuk mengisi perut mereka.",
  ui_story_5060_50600401_73_dialog_content = "Karena penasaran, Tohru, apa yang dipesan pelanggan untuk dimakan?",
  ui_story_5060_50600401_74_dialog_content = "Makanan penutup, dengan tambahan lebih banyak makanan penutup lagi. Cukup aneh untuk seorang pelanggan, ya?",
  ui_story_5060_50600401_75_dialog_content = "Mungkin karena mereka sangat kekurangan gula di sini. Aku benar-benar bisa mengerti.",
  ui_story_5060_50600401_76_dialog_content = "Bagaimanapun juga, perang melawan Eclipsite sangat berbahaya. Tanpa energi yang cukup, mereka semua akan menghadapi masalah besar.",
  ui_story_5060_50600401_77_dialog_content = "Eclipsite, ya? Sejujurnya, aku tidak merasa mereka begitu kuat... Apakah mereka benar-benar ancaman besar bagi seluruh dunia?",
  ui_story_5060_50600401_78_dialog_content = "Dibandingkan dengan Eclipsites tadi, kamu dan teman-temanmu sangat kuat sekali.",
  ui_story_5060_50600401_79_dialog_content = "Tapi di alam liar, monster-monster ini tidak menyerang dalam kelompok, melainkan dalam gelombang besar.",
  ui_story_5060_50600401_80_dialog_content = "Pertempuran kita melawan Eclipsite adalah pertempuran yang tak pernah berakhir.",
  ui_story_5060_50600401_81_dialog_content = "Dalam beberapa hal, sejarah Astra adalah sejarah perjuangan kita melawan Eclipsites.",
  ui_story_5060_50600401_82_dialog_content = "Kamu benar-benar tidak bisa lengah di dunia ini, ya?",
  ui_story_5060_50600401_83_dialog_content = "Lihat, asap!",
  ui_story_5060_50600401_84_dialog_content = "Tohru, PlayerName, lihat ke bawah sana! Para Eclipsite sedang menyerang sebuah desa!",
  ui_story_5060_50600401_85_dialog_content = "Aku melihatnya! Beri aku sebentar, dan aku akan mencari tempat untuk mendarat!",
  ui_story_5060_50600401_86_dialog_content = "Jika terlalu banyak Eclipsites menyerang, pos luar Illumina mungkin tidak akan mampu menahan mereka.",
  ui_story_5060_50600401_87_dialog_content = "Banyak orang yang terluka.",
  ui_story_5060_50600401_88_dialog_content = "Aku ingin membantu mereka...",
  ui_story_5060_50600401_89_dialog_content = "Hidup orang-orang ini sangat sulit. Semua dari mereka terlihat lelah dan takut.",
  ui_story_5060_50600401_90_dialog_content = "Yah, dan kamu bisa melihat bahwa beberapa dari mereka berasal dari daerah yang lebih jauh dan kurang terlindungi di Federasi Illumina.",
  ui_story_5060_50600401_91_dialog_content = "Um…",
  ui_story_5060_50600401_92_dialog_content = "Hah? TIDAK!",
  ui_story_5060_50600401_93_dialog_content = "...",
  ui_story_5060_50600401_94_dialog_content = "A-Aku ingin membantunya, tapi dia kabur.",
  ui_story_5060_50600401_95_dialog_content = "Kurasa setelah mengalami begitu banyak kehancuran baru saja, orang-orang ini tidak punya kekuatan untuk berurusan dengan orang asing.",
  ui_story_5060_50600401_96_dialog_content = "Kita sebaiknya tinggalkan beberapa makanan untuk mereka di sini, dan beri mereka cukup ruang untuk tenang.",
  ui_story_5060_50600401_97_dialog_content = "Ini sepertinya bukan waktu yang tepat untuk mengantarkan pesanan makanan untuk dibawa pulang...",
  ui_story_5060_50600401_98_dialog_content = "Hei! Dengar, Eclipsite busuk!",
  ui_story_5060_50600401_99_dialog_content = "Jika aku dilaporkan karena terlambat, kamu bisa mengucapkan selamat tinggal pada duniamu! Jika kamu mengerti apa yang aku katakan, maka—",
  ui_story_5060_50600401_100_dialog_content = "... Apakah orang-orang ini benar-benar tidak mampu berkomunikasi?",
  ui_story_5060_50600401_101_dialog_content = "Sepertinya aku tidak punya pilihan... Selain sedikit melanggar aturan dunia ini.",
  ui_story_5060_50600501_1_dialog_content = "Banyak sekali Eclipsite...",
  ui_story_5060_50600501_2_dialog_content = "Apa yang menyakitkan! Mereka benar-benar menyerang dalam gelombang!",
  ui_story_5060_50600501_3_dialog_content = "Jika tidak ada orang Illumina Federation yang bercampur di antara mereka, aku bisa menggoreng mereka semua dengan Nafas Naga-ku...",
  ui_story_5060_50600501_4_dialog_content = "Berusaha yang terbaik, semuanya! Aku juga akan bekerja keras untuk memberikan dukungan moril!",
  ui_story_5060_50600501_5_dialog_content = "Sini dan bantu kami!",
  ui_story_5060_50600501_6_dialog_content = "Mereka pasti telah membuat sarang di suatu tempat di dekat sini. Kita tidak akan mencapai kemajuan kecuali kita menemukannya dengan cepat dan menghancurkannya.",
  ui_story_5060_50600501_7_dialog_content = "Serahkan itu padaku! Begitu aku berubah menjadi bentuk naga...",
  ui_story_5060_50600501_8_dialog_content = "<size=45>Semua orang!</size>",
  ui_story_5060_50600501_9_dialog_content = "Prajurit Illumina dan saya baru saja selesai menghancurkan sarang di depan sana!",
  ui_story_5060_50600501_10_dialog_content = "Pertahankan barisan dan habisi sisa pasukan musuh!",
  ui_story_5060_50600501_11_dialog_content = "Biarkan setiap sisa kejahatan dihancurkan oleh kekuatan ketertiban!",
  ui_story_5060_50600501_12_dialog_content = "Ini adalah Wakil Kapten <color=#FFB400>Elma</color>!",
  ui_story_5060_50600501_13_dialog_content = "Kapten Elma terlihat sangat tajam!",
  ui_story_5060_50600501_14_dialog_content = "(Sial, aku kelaparan! Kenapa makananku belum diantar?!)",
  ui_story_5060_50600501_15_dialog_content = "(Jika makanan ini rasanya tidak enak, aku pasti akan memberikan mereka ulasan bintang satu!)",
  ui_story_5060_50600502_1_dialog_content = "Fiuh... Mereka semua pergi sekarang. Waktunya istirahat.",
  ui_story_5060_50600502_2_dialog_content = "Um…",
  ui_story_5060_50600502_3_dialog_content = "curtis 3rd party and the other the. [email and the other one was not so much  3rd, 3rd in the [email protected] [email protected] [email protected] [email protected] [email protected] [email protected] [emailie and the other one was not so. [., 3rd one was the other. [email protected]. [ and the other one was not so . [email protected] [email out of 3rd one was not rar until now. [email 3 and a day cursing that it was by the or  debuting and the other one was not so., 3rd one was not 2nd . onirtually, 3rd.y ! [email",
  ui_story_5060_50600502_4_dialog_content = "Maaf untuk sebelumnya... Aku hanya sangat takut...",
  ui_story_5060_50600502_5_dialog_content = "Itu sebabnya saya kabur... Sama sekali, sama sekali bukan karena saya tidak suka padamu.",
  ui_story_5060_50600502_6_dialog_content = "Pertarungan barusan... Sungguh luar biasa!",
  ui_story_5060_50600502_7_dialog_content = "Kamu sepertinya seumuran denganku, tapi... kamu benar-benar gagah, tajam, dan keren!",
  ui_story_5060_50600502_8_dialog_content = "Aku ingin memberikan bunga ini untukmu!",
  ui_story_5060_50600502_9_dialog_content = "Oh, dia kabur lagi.",
  ui_story_5060_50600502_10_dialog_content = "Ya, tapi sepertinya kali ini dia kabur karena malu, bukan karena takut.",
  ui_story_5060_50600502_11_dialog_content = "Sepertinya kau baru saja mendapatkan teman baru di dunia ini, Kanna!",
  ui_story_5060_50600502_12_dialog_content = "Teman...?",
  ui_story_5060_50600502_13_dialog_content = "Apakah dia akan selalu mengawasiku?",
  ui_story_5060_50600502_14_dialog_content = "Hahaha, saya yakin dia akan! Lihat, meskipun dia bersembunyi di balik batu di sana, dia masih melihatmu!",
  ui_story_5060_50600502_15_dialog_content = "Aku sudah selesai mengisi ulang sekarang.",
  ui_story_5060_50600502_16_dialog_content = "Bagus! Sekarang setelah Eclipsites sudah diurus, saatnya mengantarkan pesanan ini kepada pemilik yang berhak.",
  ui_story_5060_50600502_17_dialog_content = "Tahu, bertemu dengannya sebagai gadis pengantar di dunia ini benar-benar adalah lika-liku takdir.",
  ui_story_5060_50600502_18_dialog_content = "Cara kamu mengatakannya... Apakah kamu kenal orang yang memesan, Tohru? Aku kira itu seseorang dari Illumina Federation?",
  ui_story_5060_50600502_19_dialog_content = "Tidak, dia pasti salah satu dari kita. Tidak ada orang lain yang akan memesan seperti ini.",
  ui_story_5060_50600502_20_dialog_content = "Bukan begitu, Elma?",
  ui_story_5060_50600502_21_dialog_content = "Makanan penutupku! Akhirnya mereka datang!!!",
  ui_story_5060_50600502_22_dialog_content = "Hah? Tohru?! Apa yang kamu lakukan di sini?!",
  ui_story_5060_50600502_23_dialog_content = "Maukah kamu memakan semua itu sebelum berbicara denganku...?",
  ui_story_5060_50600502_24_dialog_content = "Aku datang untuk mengantarkan makananmu!",
  ui_story_5060_50600502_25_dialog_content = [[
, and I had to find  that * * and requirement

Text:It's not easy to find saturday night]],
  ui_story_5060_50600502_26_dialog_content = "...Dan melihat dari ukuran pesanan ini, kamu mungkin memesan satu dari setiap item di menu makanan penutup Pak Liu, bukan?!",
  ui_story_5060_50600502_27_dialog_content = "Aku tidak bisa menahan diri! Aku hampir mati kelaparan saat kita tiba di dunia ini!",
  ui_story_5060_50600502_28_dialog_content = "Tidak mudah, tapi aku berhasil menggunakan kekuatan clairvoyance-ku untuk menemukan burung kecil dengan selebaran yang terikat di kakinya...",
  ui_story_5060_50600502_29_dialog_content = "Dan semua menu terlihat sangat lezat!",
  ui_story_5060_50600502_30_dialog_content = "Jadi, aku memeriksa setiap kotak di menu pencuci mulut dan membuat saus celup dari cairan Eclipsite!",
  ui_story_5060_50600502_31_dialog_content = "Setelah itu, aku mengikatkan menu kembali di kaki burung itu dan membiarkannya terbang pergi!",
  ui_story_5060_50600502_32_dialog_content = "Namun kemudian aku mulai merasa sangat lapar lagi ketika Eclipsites menyerang kami lebih banyak. Aku khawatir karena mungkin aku tidak berhasil memesan dengan benar, mengingat makananku tidak pernah datang.",
  ui_story_5060_50600502_33_dialog_content = "Tapi pada akhirnya, itu muncul tepat waktu! Heeheehee!",
  ui_story_5060_50600502_34_dialog_content = "Saya mengerti. Kalau begitu—",
  ui_story_5060_50600502_35_dialog_content = "Terima kasih sudah berbelanja di sini! Jika Anda menikmati makanannya, jangan lupa berikan kami peringkat bintang lima!",
  ui_story_5060_50600502_36_dialog_content = "Ini tagihan untuk makanan ditambah pengiriman!",
  ui_story_5060_50600502_37_dialog_content = "Hah? Apa katamu?",
  ui_story_5060_50600502_38_dialog_content = "<size=45>Ini tagihan untuk makanan ditambah pengiriman!</size>",
  ui_story_5060_50600502_39_dialog_content = "...D-Apakah Anda menerima Yen Jepang, kebetulan...?",
  ui_story_5060_50600502_40_dialog_content = "Jangan bercanda, pelanggan yang terhormat! Toko kami hanya menerima Nightium, seperti yang pasti Anda tahu!",
  ui_story_5060_50600502_41_dialog_content = "Jadi, serahkan—semua—Nightium-mu—",
  ui_story_5060_50600502_42_dialog_content = "...Kamu terlalu menakutkan, Tohru!",
  ui_story_5060_50600502_43_dialog_content = "Saya akan menanggung tagihan Wakil Kapten. Bagaimanapun, dia telah menyelamatkan hidup kita.",
  ui_story_5060_50600502_44_dialog_content = "Hitung saya masuk! Kekuatan Wakil Kapten ini lebih berharga daripada beberapa Nightium!",
  ui_story_5060_50600502_45_dialog_content = "*Sniffle* A... Aku sangat terharu, semuanya!",
  ui_story_5060_50600502_46_dialog_content = "Mari kita istirahat dan berkumpul untuk sementara waktu, agar kita bisa menyerang kamp utama Eclipsite! Kita akan membasmi mereka semua!",
  ui_story_5060_50600502_47_dialog_content = "Jayalah Illumina!!",
  ui_story_5060_50600502_48_dialog_content = "...",
  ui_story_5060_50600502_49_dialog_content = "PlayerName terlalu tercengang untuk bicara.",
  ui_story_5060_50600502_50_dialog_content = "Kamu masih sama konyolnya seperti biasanya, Elma.",
  ui_story_5060_50600502_51_dialog_content = "Sebagai naga yang taat hukum dari Faksi Harmony, saya terkejut bahwa Anda juga menjalankan tanggung jawab Anda di dunia ini.",
  ui_story_5060_50600502_52_dialog_content = "A-Aku punya alasan yang baik untuk itu... Dan kau juga, Tohru!",
  ui_story_5060_50600502_53_dialog_content = "Lihat saja kamu... Seorang pembantu naga mengantarkan makanan timur dengan sepeda motor...",
  ui_story_5060_50600502_54_dialog_content = "Kamu sama sekali tidak bertindak seperti naga dari Faksi Chaos!",
  ui_story_5060_50600502_55_dialog_content = "Seperti yang aku katakan, aku hanya melakukan ini untuk menemukan kalian semua agar kita bisa pulang lebih cepat!",
  ui_story_5060_50600502_56_dialog_content = "Tohru dan Elma seperti api dan air, seperti biasanya.",
  ui_story_5060_50600502_57_dialog_content = "Heheheh, kamu masih belum paham perasaan antara musuh lama, Kanna.",
  ui_story_5060_50600502_58_dialog_content = "Kalian berdua mungkin terlihat sedang bertengkar, tapi sebenarnya kalian tidak saling membenci, 'kan? Malah, kalian mungkin saling mengerti dengan sangat baik!",
  ui_story_5060_50600502_59_dialog_content = "Kini pertempuran telah berakhir dan semua orang dari Federasi Illumina akan kembali...",
  ui_story_5060_50600502_60_dialog_content = "Mengapa kita tidak duduk dan makan dulu? Lalu kita bisa membicarakan mencari informasi lebih lanjut di sekitar sini.",
  ui_story_5060_50600502_61_dialog_content = "Semua orang lapar, dan satu-satunya yang makan adalah Elma...",
  ui_story_5060_50600502_62_dialog_content = "...Tapi aku yakin dia bisa makan satu kali lagi.",
  ui_story_5060_50600502_63_dialog_content = "Baiklah, hitung saya juga! Mari rayakan kemenangan kita dengan pesta besar yang meriah!",
  ui_story_5060_50600502_64_dialog_content = "Baunya lezat sekali!",
  ui_story_5060_50600502_65_dialog_content = "Makanan ini luar biasa! Aku bisa merasakan kekuatanku kembali!",
  ui_story_5060_50600502_66_dialog_content = "Hahaha, senang kau suka! Seorang teman mengajariku cara membuat ini beberapa waktu lalu.",
  ui_story_5060_50600502_67_dialog_content = "Seperti yang diharapkan, kami Aurorian dan Caelestite adalah pasangan yang sempurna!",
  ui_story_5060_50600502_68_dialog_content = "Tapi kamu kan naga.",
  ui_story_5060_50600502_69_dialog_content = "Semua orang di sini terus mengatakan itu, tapi aku tidak khawatirkan detail kecil seperti itu!",
  ui_story_5060_50600502_70_dialog_content = "Huh, apa yang akan kita lakukan denganmu...",
  ui_story_5060_50600502_71_dialog_content = "Aku juga membawa roti kukus dari Pak Liu. Cobalah satu, semuanya!",
  ui_story_5060_50600502_72_dialog_content = "Simpan beberapa untuk saya, Tohru!",
  ui_story_5060_50600502_73_dialog_content = "Kanna sempat mengatakan bahwa kalian berdua itu seperti air dan api, bukan?",
  ui_story_5060_50600502_74_dialog_content = "Orang biasanya tidak menggambarkan teman dengan cara itu. Apa cerita di antara kalian berdua?",
  ui_story_5060_50600502_75_dialog_content = "Kurasa bisa dibilang kita berteman sekarang, meskipun dulu kita adalah musuh bebuyutan.",
  ui_story_5060_50600502_76_dialog_content = "Saya naga dari Faksi Kekacauan, sedangkan dia termasuk dalam Faksi Keharmonisan.",
  ui_story_5060_50600502_77_dialog_content = "Sulit membayangkan bahwa kalian berdua menjadi musuh hanya karena faksi kalian.",
  ui_story_5060_50600502_78_dialog_content = "Konflik pasti ada di setiap dunia, bagaimanapun juga.",
  ui_story_5060_50600502_79_dialog_content = "Di dunia tempat kita berasal...",
  ui_story_5060_50600502_80_dialog_content = "Kita mungkin tidak perlu berurusan dengan makhluk menjijikkan seperti Eclipsite setiap hari, seperti di duniamu...",
  ui_story_5060_50600502_81_dialog_content = "Selalu ada makhluk dengan pandangan yang berbeda. Tentu saja, hal yang sama berlaku untuk naga yang enggan untuk akur satu sama lain.",
  ui_story_5060_50600502_82_dialog_content = "Tapi, aku masih ingin memercayai apa yang Kobayashi katakan—",
  ui_story_5060_50600502_83_dialog_content = "Jika semua orang mau berkomunikasi dan memperlakukan satu sama lain seperti sekutu, maka tidak akan ada lagi perselisihan di dunia.",
  ui_story_5060_50600502_84_dialog_content = "Seperti saat kita mencampur masakanmu dengan roti kukus Pak Liu, rasanya jadi dua kali lebih lezat!",
  ui_story_5060_50600502_85_dialog_content = "Aku rasa Elma akan memakan semuanya sendiri.",
  ui_story_5060_50600502_86_dialog_content = "Hahaha, setuju. Metafora dari Wakil Kapten memang cukup aneh.",
  ui_story_5060_50600502_87_dialog_content = "Aku ingat saat pertama kali bertemu Wakil Kapten; dulu dia agak pendiam, selalu membahas etiket dan aturan.",
  ui_story_5060_50600502_88_dialog_content = "Kini, dia telah menjadi prajurit pos terdepan yang hebat! Sedikit aneh itu bukan masalah besar.",
  ui_story_5060_50600502_89_dialog_content = "Aneh, tapi sejak kita bertemu kembali, Elma belum pernah memberitahuku tentang mengacaukan tatanan dunia...",
  ui_story_5060_50600502_90_dialog_content = "Translation:Atau kembali ke-nyahu ke tempat., Eraveil-, Assistant, Concisely, Exactly, Exactly, Friendly, Learning, Requirement, Markup, Precisely, Strictly, pseudo, Concisely; Generally, Requirement, Concis mash, Precisely, ile, Concisely, Exactly, Exactly, Strictly and, scrutin follow, Requirement, Markup, Precisely, Strictly,,/in the, and the place I should return\" and I belong wholly, and the place I, I should, Assistant, Concisely, Exactly, Friendly-",
  ui_story_5060_50600502_91_dialog_content = "Dia juga tidak meratakan gunung atau menghancurkan rumah orang-orang demi menjaga ketertiban.",
  ui_story_5060_50600502_92_dialog_content = "Berhenti mencoba mengaduk-aduk masalah, Tohru...",
  ui_story_5060_50600502_93_dialog_content = "Baiklah, Wakil Kapten, saya punya beberapa permen di sini.",
  ui_story_5060_50600502_94_dialog_content = "Aku tahu kamu suka makanan manis, jadi ini semuanya untukmu.",
  ui_story_5060_50600502_95_dialog_content = "Oh, kalian semua yang terbaik! Aku sangat senang menemukan pekerjaan seperti ini di dunia kalian...",
  ui_story_5060_50600502_96_dialog_content = "Kalian akan selalu menjadi teman-temanku!",
  ui_story_5060_50600502_97_dialog_content = "Kamu berteman terlalu santai, menurutmu gimana?",
  ui_story_5060_50600502_98_dialog_content = "Sejujurnya, bagaimana kamu bisa beradaptasi dengan lingkungan apa pun yang kamu temui?",
  ui_story_5060_50600502_99_dialog_content = "Apakah semua orang di Faksi Harmony memiliki bakat ini?",
  ui_story_5060_50600601_1_dialog_content = "Kita menemui para penjahat yang PlayerName sebutkan! Mereka datang ke sini dari Rediesel Desert.",
  ui_story_5060_50600601_2_dialog_content = "Saat itu, kami mengetahui bahwa orang-orang ini mencoba menyelinap melewati pos jaga kami dengan menggunakan metode yang dilarang.",
  ui_story_5060_50600601_3_dialog_content = "Saat kami sedang bernegosiasi dan mencoba menangkap mereka, kami disergap oleh Eclipsites dan gagal membawa mereka masuk.",
  ui_story_5060_50600601_4_dialog_content = "Semua berkat intervensi Wakil Kapten Elma, kita terselamatkan; jika tidak, kita pasti akan terkubur di bawah pasir kuning.",
  ui_story_5060_50600601_5_dialog_content = "Jangan sebut itu! Kalian juga menyelamatkan saya dari kelaparan di alam liar, ingat?",
  ui_story_5060_50600601_6_dialog_content = "Nah, sepertinya kita akan menemukan benteng atau jalur transportasi para penyelundup di suatu tempat di Gurun Rediesel.",
  ui_story_5060_50600601_7_dialog_content = "Datang ke Pos Luar Illumina ini memang keputusan yang tepat, ternyata!",
  ui_story_5060_50600601_8_dialog_content = "Namun kami masih belum mendengar apa-apa tentang Fafnir.",
  ui_story_5060_50600601_9_dialog_content = "Itu benar. Saya meminta beberapa orang menyusup ke jaringan intelijen Illumina untuk mencari informasi lebih lanjut, tetapi kami tidak menemukan apa-apa.",
  ui_story_5060_50600601_10_dialog_content = "Tapi tidak perlu khawatir. Fafnir adalah tipe orang yang bisa bertahan di mana pun dia berada.",
  ui_story_5060_50600601_11_dialog_content = "Dan siapa tahu? Mungkin kita akan bertemu dengan teman yang hilang terakhir kamu di alamat pengiriman berikutnya?",
  ui_story_5060_50600601_12_dialog_content = "Ternyata, dunia ini bisa cukup sempit.",
  ui_story_5060_50600601_13_dialog_content = "Kau benar.",
  ui_story_5060_50600601_14_dialog_content = "Makanan apa yang akan kita antar kali ini, Tohru?",
  ui_story_5060_50600601_15_dialog_content = "Ini sebenarnya bukan pesanan makanan. Toko ini suka berterima kasih kepada pelanggan tetapnya dengan beberapa saus spesial, jadi itulah yang akan kita antarkan.",
  ui_story_5060_50600601_16_dialog_content = "Dan alamatnya ada di... Gurun Rediesel? Wah, betapa kebetulan. Apakah Fafnir juga akan muncul di sana?",
  ui_story_5060_50600601_17_dialog_content = "Ingat apa yang dikatakan para penyelundup itu? Mereka mengambil risiko untuk diburu oleh seekor naga hanya untuk mencuri semacam harta karun darinya.",
  ui_story_5060_50600601_18_dialog_content = "Naga dari koleksi lelang?",
  ui_story_5060_50600601_19_dialog_content = "Ketika saya mendengar pembicaraan penyelundup, saya yakin mereka pasti tidak membahas tentang Fafnir.",
  ui_story_5060_50600601_20_dialog_content = "Tidak peduli di dunia mana dia berada atau siapa lawannya, Fafnir akan menggunakan segala cara untuk mendapatkan harta karun.",
  ui_story_5060_50600601_21_dialog_content = "Apakah temanmu benar-benar menakutkan?",
  ui_story_5060_50600601_22_dialog_content = "Jangan khawatir, dia dikenal bisa bergaul dengan damai dengan orang lain! Hanya saja tidak terlalu banyak orang!",
  ui_story_5060_50600601_23_option_content = "Masih terdengar sedikit menakutkan...",
  ui_story_5060_50600601_24_option_content = [[
1.2-t op 1, the dragon's back.)
 2. Strict:
, where the dragon's back.]],
  ui_story_5060_50600601_25_dialog_content = "Tenang, kamu bersama kami, ingat? Jika yang terburuk terjadi, kita akan mengeroyok dia!",
  ui_story_5060_50600601_26_dialog_content = "Meskipun aku masih cukup takut, kita harus terus melanjutkan...",
  ui_story_5060_50600601_27_dialog_content = "Saatnya mengakhiri insiden penyelundupan lelang ini!",
  ui_story_5060_50600601_28_dialog_content = "Aku juga berjanji hal yang sama pada bosku. Jika ada yang bisa kulakukan untuk membantu, akan kubantu sebisaku!",
  ui_story_5060_50600601_29_dialog_content = "Lucoa bisa sangat bisa diandalkan ketika dia tidak menganggur.",
  ui_story_5060_50600601_30_dialog_content = "Apakah kamu tahu persis di mana menemukan alamat ini, PlayerName?",
  ui_story_5060_50600601_31_dialog_content = "Saya cukup familiar dengan itu. Ini salah satu benteng kuat Rediesel Wrench.",
  ui_story_5060_50600601_32_dialog_content = "Sekarang setelah kupikirkan, sepertinya sudah waktunya untuk pergi ke sana.",
  ui_story_5060_50600601_33_dialog_content = "Meskipun mereka memulung di gurun, mereka juga tahu cara melakukan perdagangan yang jujur.",
  ui_story_5060_50600601_34_dialog_content = "Tapi jika kita ingin memasuki wilayah mereka dengan aman, lebih baik jika kamu biarkan aku menyapa mereka terlebih dahulu.",
  ui_story_5060_50600601_35_dialog_content = "PlayerName sangat bisa diandalkan.",
  ui_story_5060_50600601_36_dialog_content = "Tohru, tinggalkan motormu bersama prajurit-prajurit ini, agar mereka bisa membawanya kembali ke pos luar. Jika tidak, kemungkinan besar orang-orang Rediesel Wrench akan mencoba mengambilnya.",
  ui_story_5060_50600601_37_dialog_content = "Meskipun biasanya mereka berkendara dengan kendaraan mereka sendiri, lebih baik untuk selalu siap sedia.",
  ui_story_5060_50600601_38_dialog_content = "Jangan khawatir, Nona Tohru. Kami akan mengurus sepeda motor ini!",
  ui_story_5060_50600601_39_dialog_content = "Kemana perginya penyelundup-penyelundup tak berguna itu?!",
  ui_story_5060_50600601_40_dialog_content = "Sepertinya penyelundup sudah melewati Rediesel Wrench. Mereka pasti tidak takut pada siapa pun...",
  ui_story_5060_50600601_41_dialog_content = "Izinkan aku memperkenalkan semua orang! Ini dia Sinsa, pemimpin saat ini dari Rediesel Wrench.",
  ui_story_5060_50600601_42_dialog_content = "Dan di sini adalah teman-teman terbaru saya!",
  ui_story_5060_50600601_43_dialog_content = "Orang ini terlihat sangat tangguh! Mau lihat siapa yang lebih tangguh, orang besar?",
  ui_story_5060_50600601_44_dialog_content = "Maaf, tapi saya tidak pernah memukul wanita dalam hidup saya, apalagi seorang pembantu.",
  ui_story_5060_50600601_45_dialog_content = "Hei, PlayerName! Kamu bilang kamu tahu sesuatu tentang penyelundup busuk itu, kan? Aku tidak akan beristirahat sampai aku menghajar orang-orang bodoh itu terlebih dahulu!",
  ui_story_5060_50600601_46_dialog_content = "Jangan bilang mereka mencuri sesuatu darimu?",
  ui_story_5060_50600601_47_dialog_content = "Tidak mungkin! Orang-orang itu bisa sepuluh kali lebih berani, dan mereka tetap tidak akan punya keberanian untuk mencuri dari kita!",
  ui_story_5060_50600601_48_dialog_content = "Sebenarnya, penyelundup-penyelundup ini dulunya cukup tenang di sini di Gurun Rediesel.",
  ui_story_5060_50600601_49_dialog_content = "Aku tidak tahu apa yang ada di pikiran mereka, tapi akhir-akhir ini mereka membuat berbagai masalah.",
  ui_story_5060_50600601_50_dialog_content = "Mereka hampir terlihat seperti orang linglung, berlarian dan berteriak tentang monster dan \"kiamat yang akan datang\" atau apapun itu!",
  ui_story_5060_50600601_51_dialog_content = "Mereka sudah sangat mempengaruhi operasi sehari-hari kita!",
  ui_story_5060_50600601_52_dialog_content = "Karena mereka, hampir tidak ada karavan Lumopolis yang melintasi gurun!",
  ui_story_5060_50600601_53_dialog_content = "Oh... Eh...",
  ui_story_5060_50600601_54_dialog_content = "Apakah kamu benar-benar punya informasi tentang mereka? Kalau iya, cepat katakan saja!",
  ui_story_5060_50600601_55_dialog_content = "K-Kami ingin menanyakan lebih banyak informasi tentang mereka kepada Anda.",
  ui_story_5060_50600601_56_dialog_content = "Seperti jika mereka baru saja kehilangan harta karun?",
  ui_story_5060_50600601_57_dialog_content = "Bergabunglah dengan Rediesel Wrench, dan mungkin aku akan bersedia memberitahumu.",
  ui_story_5060_50600601_58_dialog_content = "Tidak lagi abad., saya lagi..., 200.  by. 2006. 2006. 2006. 200. , 2006. .",
  ui_story_5060_50600601_59_dialog_content = "Dia yang mengawasi segala sesuatu di sekitar sini.",
  ui_story_5060_50600601_60_dialog_content = "Kamu tampak sangat populer, PlayerName.",
  ui_story_5060_50600601_61_dialog_content = "Oh, iya, hampir saja aku lupa.",
  ui_story_5060_50600601_62_dialog_content = "Izinkan saya memperkenalkan diri! Namaku Tohru, seorang pelayan pengantar pesanan dari restoran Pak Liu!",
  ui_story_5060_50600601_63_dialog_content = "Apakah ada di sini salah satu pelanggan tetap Tuan Liu? Jika iya, saya ada saus untuk diantarkan atas namanya!",
  ui_story_5060_50600601_64_dialog_content = "Whoa, nggak pernah kepikiran bisa dapet barang bagus ini?! Serahkan, cepat!",
  ui_story_5060_50600601_65_dialog_content = "Aku sudah beberapa kali yang pergi mengambilnya; kenapa harus aku yang memberikannya padamu?!",
  ui_story_5060_50600601_66_dialog_content = "Ini voucher milikku yang selama ini kalian semua gunakan!",
  ui_story_5060_50600601_67_dialog_content = "Berhenti berdebat atau aku akan menyita semuanya!",
  ui_story_5060_50600601_68_dialog_content = "Ayo kembali ke benteng Rediesel Wrench terlebih dahulu. Ayolah, PlayerName; kamu dan teman-temanmu bisa ikut denganku.",
  ui_story_5060_50600601_69_dialog_content = "Yang lainnya bisa mengikuti di belakang dengan mobil yang lain!",
  ui_story_5060_50600601_70_dialog_content = "Tentu saja.",
  ui_story_5060_50600601_71_dialog_content = "Baiklah, teman-teman! Saatnya merasakan kecepatan dan keseruan dari Rediesel Wrench!",
  ui_story_5060_50600601_72_dialog_content = "Sekarang bertahanlah dengan kencang!",
  ui_story_5060_50600601_73_dialog_content = "<size=45>Lepas landas!</size>",
  ui_story_5060_50600601_74_dialog_content = "Woo-hoo! Cara mengemudi yang luar biasa!",
  ui_story_5060_50600601_75_dialog_content = "Kamu baik-baik saja, Kanna?",
  ui_story_5060_50600601_76_dialog_content = "Aku baik-baik saja. Ini menyenangkan.",
  ui_story_5060_50600601_77_dialog_content = "Itu bagus, tapi sepertinya ada yang salah dengan PlayerName!",
  ui_story_5060_50600601_78_dialog_content = "Kamu tidak mabuk kendaraan, kan?",
  ui_story_5060_50600601_79_dialog_content = "Seorang pilot Colossus tidak mungkin mabuk kendaraan!",
  ui_story_5060_50600601_80_dialog_content = "Tahu nggak sih, memaksakan diri itu nggak baik?",
  ui_story_5060_50600601_81_dialog_content = "Bersandarlah padaku dan semuanya akan baik-baik saja!",
  ui_story_5060_50600601_82_dialog_content = "N... Tidak, terima kasih.",
  ui_story_5060_50600601_83_dialog_content = "Apakah kamu mer 12v Lith, Rediesel--Leger, atau lebih dikenal, yang diterbit di dalam negeri? troubles, meng] meng, menga,'-G",
  ui_story_5060_50600601_84_dialog_content = "Bagian berikutnya akan sedikit bergelombang, jadi coba untuk tidak terlempar!",
  ui_story_5060_50600601_85_dialog_content = "Sebelum bertemu dengan kamu, aku terus penasaran bagaimana Rediesel Wrench itu.",
  ui_story_5060_50600601_86_dialog_content = "Ternyata, PlayerName bilang kamu tipe orang yang akan paksa ambil motor milikku!",
  ui_story_5060_50600601_87_dialog_content = "Kupikir kalian akan menjadi sekelompok preman dengan sikap buruk...",
  ui_story_5060_50600601_88_dialog_content = "Tapi sekarang saya sadar bahwa salah berpikir seperti itu.",
  ui_story_5060_50600601_89_dialog_content = "Hahaha, jangan khawatir tentang itu! Kita semua membuat kesalahan sesekali!",
  ui_story_5060_50600601_90_dialog_content = "Tapi selama kita berbicara dengan terbuka dan saling percaya, kita akan selalu menjadi teman yang berlari melintasi gurun gila ini!",
  ui_story_5060_50600601_91_dialog_content = "Rediesel Wrench adalah tentang kebebasan!",
  ui_story_5060_50600601_92_dialog_content = "Menurutku, kebebasan yang terlalu berlebihan—",
  ui_story_5060_50600801_1_dialog_content = "Aku merasa pusing.",
  ui_story_5060_50600801_2_dialog_content = "Sungguh pusing.",
  ui_story_5060_50600801_3_dialog_content = "Kemari, Kanna. Biarkan aku memelukmu.",
  ui_story_5060_50600801_4_dialog_content = "Aku tidak menyangka kamu yang akhirnya mabuk kendaraan.",
  ui_story_5060_50600801_5_dialog_content = "Tidak ada cara membantu; lagipula, dia masih sangat muda dan saya yakin ini adalah pertama kalinya dia mengalami perjalanan yang begitu penuh liku.",
  ui_story_5060_50600801_6_dialog_content = "Ngomong-ngomong, aku mulai merasa sedikit lapar nih. Kapan kita bisa makan?",
  ui_story_5060_50600801_7_dialog_content = "Jadi, selama ini kamu diam saja karena tidak ingin merasa lapar saat berbicara, ya?",
  ui_story_5060_50600801_8_dialog_content = "T-Tidak! Aku selalu waspada terhadap Eclipsite sepanjang waktu!",
  ui_story_5060_50600801_9_dialog_content = "Kita berhasil mengalahkan banyak dari mereka sebelumnya. Kamu bisa makan sebanyak yang kamu inginkan.",
  ui_story_5060_50600801_10_dialog_content = "Bagaimana aku bisa makan sesuatu seperti itu?!",
  ui_story_5060_50600801_11_dialog_content = "Nah, bagaimana dengan permen yang diberikan tentara Illuminan itu padamu?",
  ui_story_5060_50600801_12_dialog_content = "Itu adalah tanda kekompakan kita!",
  ui_story_5060_50600801_13_dialog_content = "Aku berencana membawa itu pulang bersama kita! Tidak akan ada artinya jika aku memakannya sekarang!",
  ui_story_5060_50600801_14_dialog_content = "Ah, lupakan saja... Ini. Pak Liu memberiku beberapa tambahan, tapi aku tidak bisa memakannya semua.",
  ui_story_5060_50600801_15_dialog_content = "Kamu memang teman yang baik, Tohru!",
  ui_story_5060_50600801_16_dialog_content = "G-Lepaskan aku!",
  ui_story_5060_50600801_17_dialog_content = "Meskipun baru saja bertarung sengit, kalian berdua tampaknya masih penuh energi.",
  ui_story_5060_50600801_18_dialog_content = "Apakah kamu membicarakan tentang Eclipsites di gurun itu? Mengatasi hama seperti mereka bukanlah masalah bagi seseorang seperti aku!",
  ui_story_5060_50600801_19_dialog_content = "Namun, ketika kami akhirnya sampai di gurun, aku pikir jumlah mereka di sini akan jauh lebih sedikit.",
  ui_story_5060_50600801_20_dialog_content = "Lalu mengapa masih ada begitu banyak Eclipsite?",
  ui_story_5060_50600801_21_dialog_content = "Jika ada satu hal yang tidak kekurangan di dunia ini, itu adalah Eclipsite. Di mana pun Anda menemukan Aurorian, monster-monster itu tidak akan pernah terlalu jauh—",
  ui_story_5060_50600801_22_dialog_content = "Tapi bahkan tempat tanpa Aurorian pun dipenuhi dengan Eclipsite!",
  ui_story_5060_50600801_23_dialog_content = "Nah, berkat sistem pengawasan luas Odi, kita bisa melacak sebagian besar gerakan mereka dan bersiap sesuai kebutuhan.",
  ui_story_5060_50600801_24_dialog_content = "Ini juga membantu kamu mempertahankan benteng-bentengmu dari pasukan Lumopolis, kan?",
  ui_story_5060_50600801_25_dialog_content = "Ha ha ha! Blak-blakan seperti biasa, PlayerName! Itulah yang aku suka darimu!",
  ui_story_5060_50600801_26_dialog_content = "Baiklah, Odi seharusnya ada di dalam. Tanyakan padanya apa pun yang kamu inginkan.",
  ui_story_5060_50600801_27_dialog_content = "Odi—",
  ui_story_5060_50600801_28_dialog_content = "Hah? Siapa yang di sebelahnya itu?",
  ui_story_5060_50600801_29_dialog_content = "Kamu cukup hebat, <color=#FFB400>Fafnir</color>, tapi jika kamu ingin mengalahkan saya...",
  ui_story_5060_50600801_30_dialog_content = "Kamu masih memiliki perjalanan yang panjang!",
  ui_story_5060_50600801_31_dialog_content = "Ambil ini—",
  ui_story_5060_50600801_32_dialog_content = "<size=45>Star Piercer!</size>",
  ui_story_5060_50600801_33_dialog_content = "Tunggu, jangan gunakan gerakan itu!",
  ui_story_5060_50600801_34_dialog_content = "...",
  ui_story_5060_50600801_35_dialog_content = "Fafnir terlihat sangat terluka; dia bahkan tidak menyapa kami saat kami masuk.",
  ui_story_5060_50600801_36_dialog_content = "Hei Fafnir, kamu masih hidup?",
  ui_story_5060_50600801_37_dialog_content = "Kupikir jiwa dia sudah meninggalkan tubuhnya. Dia pasti kalah sangat buruk.",
  ui_story_5060_50600801_38_dialog_content = "Aku tidak kalah. Aku hanya sedang tidak semangat, itu saja.",
  ui_story_5060_50600801_39_dialog_content = "Lama tidak bertemu, PlayerName! Apakah kamu membawa teman-teman baru ini untuk bermain game hari ini?",
  ui_story_5060_50600801_40_dialog_content = "Ya. Dan mereka juga kebetulan merupakan teman dari Fafnir juga.",
  ui_story_5060_50600801_41_dialog_content = "(Jadi ini Fafnir... Dia memiliki tatapan yang sangat ganas di matanya.)",
  ui_story_5060_50600801_42_dialog_content = "(Pada saat seperti ini, ucapan ramah tampaknya sangat penting untuk menutup jarak di antara kita.)",
  ui_story_5060_50600801_43_dialog_content = "Hai Faffy! Namaku PlayerName, dan aku salah satu dari Tohru...",
  ui_story_5060_50600801_44_dialog_content = "Jangan menyebutku dengan nama yang tidak formal seperti itu.",
  ui_story_5060_50600801_45_dialog_content = "Eh... Pokoknya, kami datang ke sini untuk meminta sedikit informasi dari Odi.",
  ui_story_5060_50600801_46_dialog_content = "Selama kau tidak memintaku untuk bergabung dengan Rediesel Wrench, kami akan menyetujui segala syarat yang kau berikan kepada kami.",
  ui_story_5060_50600801_47_dialog_content = "\"Kondisi\"? Saya tidak peduli tentang itu! Baru saja saya mengalahkan orang ini tiga ratus kali berturut-turut, jadi suasana hati saya sangat baik!",
  ui_story_5060_50600801_48_dialog_content = "Koreksi: itu adalah dua ratus sembilan puluh sembilan kali.",
  ui_story_5060_50600801_49_dialog_content = "Yah, cukup dekat. Pokoknya, aku akan membantumu secara gratis kali ini.",
  ui_story_5060_50600801_50_dialog_content = "(Terima kasih, <size=45>Faffy!</size>)",
  ui_story_5060_50600801_51_dialog_content = "Translation:Translation:Translation:mp, it, Translation:Translation:Translation:Translation:, Translation:Translation:Translation:Translation, Translation, Translation:, Translation::Translation:Translation:Translation:Translation-, Translation: cation NE and‘ o,  BE in...  in the 3",
  ui_story_5060_50600801_52_dialog_content = "Jadi selama ini kamu bersama Rediesel Wrench, Fafnir?",
  ui_story_5060_50600801_53_dialog_content = "Kamu adalah naga yang mengumpulkan harta karun, tetapi jika dilihat dari sifat mereka... Sudah jelas bahwa Rediesel Wrench adalah kelompok pemburu harta karun.",
  ui_story_5060_50600801_54_dialog_content = "Sejujurnya, aku terkejut kau bertahan selama ini...",
  ui_story_5060_50600801_55_dialog_content = "Apakah mereka menyuapmu dengan persediaan permen seumur hidup atau semacamnya?!",
  ui_story_5060_50600801_56_dialog_content = "Fafnir tidak seperti kamu yang rakus, Elma.",
  ui_story_5060_50600801_57_dialog_content = "Selama lawan saya mendapatkan persetujuan saya, saya tidak masalah berinteraksi dengan mereka sebagai setara.",
  ui_story_5060_50600801_58_dialog_content = "Ini sama sekali tidak ada hubungannya dengan profesi, status, atau nilai di masyarakat.",
  ui_story_5060_50600801_59_dialog_content = "Kau mau ke mana, Fafnir?",
  ui_story_5060_50600801_60_dialog_content = "Aku keluar mencari udara segar.",
  ui_story_5060_50600801_61_dialog_content = "Bagaimana aku bisa kalah begitu menyedihkan? Di mana kesalahanku?",
  ui_story_5060_50600801_62_dialog_content = "Apakah ini masalah tekad?",
  ui_story_5060_50600802_1_dialog_content = "Apa yang kamu inginkan? Aku masih memikirkan cara untuk mengalahkan Odi.",
  ui_story_5060_50600802_2_dialog_content = "Jangan khawatir, kamu akan punya banyak waktu di masa depan untuk memikirkannya nanti.",
  ui_story_5060_50600802_3_dialog_content = "Sekarang kembali masuk saja. Odi ada sesuatu yang ingin diberitahu kepada kamu.",
  ui_story_5060_50600802_4_dialog_content = "Hmph... Pasti dia hanya ingin membanggakan kemenangannya.",
  ui_story_5060_50600802_5_dialog_content = "Aku benci mengakui ini, tapi saat ini... Dia lebih baik dariku.",
  ui_story_5060_50600802_6_dialog_content = "Lebih baik kamu jaga nada bicaramu.",
  ui_story_5060_50600802_7_dialog_content = "Jika kau terlalu jauh, mungkin saja aku akan mengutukmu menjadi debu.",
  ui_story_5060_50600802_8_dialog_content = "Apa sih yang sedang dia omongkan?",
  ui_story_5060_50600802_9_dialog_content = "Jangan hiraukan dia, dia hanya suka terdengar keren!",
  ui_story_5060_50600802_10_dialog_content = "Kamu lari begitu cepat tadi sampai-sampai aku tidak punya waktu untuk memberikan hadiahku.",
  ui_story_5060_50600802_11_dialog_content = "Hadiahmu. Untukku?",
  ui_story_5060_50600802_12_dialog_content = "Di sini, ini adalah versi terbaru dari mesin game ini.",
  ui_story_5060_50600802_13_dialog_content = "Semangat, Fafnir! Tangan jeniusku membuat ini dari awal, yang membuatnya sama berharganya dengan harta karun lainnya!",
  ui_story_5060_50600802_14_dialog_content = "Jadi kamu tidak akan mempermalukan saya?",
  ui_story_5060_50600802_15_dialog_content = "Menghina kamu? Tak perlu lagi untuk itu. Lagipula, sudah lama aku mengakui kamu sebagai lawan yang sepadan.",
  ui_story_5060_50600802_16_dialog_content = "Bahkan seorang pecandu game seperti Gronru tidak dapat memberikan data uji yang saya butuhkan dengan mesin game ini.",
  ui_story_5060_50600802_17_dialog_content = "Kamu adalah orang pertama dan satu-satunya yang bertanding 300 ronde melawanku, dan aku sangat berterima kasih untuk itu!",
  ui_story_5060_50600802_18_dialog_content = "Baiklah, sekarang saatnya untuk menangani permintaan PlayerName.",
  ui_story_5060_50600802_19_dialog_content = "Bisakah saya tanya bagaimana rencanamu untuk melakukannya?",
  ui_story_5060_50600802_20_dialog_content = "Sederhana saja! Pertama, saya akan membuat sistem pengawasan melakukan pencarian otomatis, lalu saya akan membandingkan gambar yang muncul.",
  ui_story_5060_50600802_21_dialog_content = "Yah... Aku sama sekali tidak mengerti cara kerjanya. Lupakan saja aku yang bertanya.",
  ui_story_5060_50600802_22_dialog_content = "Dan berapa lama waktu yang dibutuhkan?",
  ui_story_5060_50600802_23_dialog_content = "Sekitar dua puluh menit.",
  ui_story_5060_50600802_24_dialog_content = "Mengapa kamu bolak-balik terus, Fafnir? Biar kutebak, kamu berencana memberikan buku di tanganmu itu sebagai hadiah untuk Odi?",
  ui_story_5060_50600802_25_dialog_content = "Itu bukan urusan Anda.",
  ui_story_5060_50600802_26_dialog_content = "Ayo kita lihat buku macam apa ini.",
  ui_story_5060_50600802_27_dialog_content = "Oh, bukan lagi buku kutukan bodohmu ini!",
  ui_story_5060_50600802_28_dialog_content = "Nona Odi memiliki rasa haus akan pengetahuan yang tak terpuaskan! Jika dia melihat buku ini, siapa tahu apa yang akan terjadi?!",
  ui_story_5060_50600802_29_dialog_content = "Mengapa kamu tidak memberikan hadiah yang berbeda untuknya saja?",
  ui_story_5060_50600802_30_dialog_content = "Cih.",
  ui_story_5060_50600802_31_dialog_content = "Yang mengingatkan saya, kita juga harus memberikan teman-teman baru kita dari Rediesel Wrench beberapa hadiah kenang-kenangan!",
  ui_story_5060_50600802_32_dialog_content = "Uh, Nona Tohru?",
  ui_story_5060_50600802_33_dialog_content = "Kenapa kamu... Terus menatapku seperti itu? Apakah ada sesuatu yang menempel di ekorku?",
  ui_story_5060_50600802_34_dialog_content = "Sama sekali tidak! Aku hanya berpikir bahwa dengan ekor besar dan indah seperti milikmu... Kamu akan terlihat sangat cantik dengan kostum pembantu, Maggie!",
  ui_story_5060_50600802_35_dialog_content = "Pernahkah kamu berpikir untuk memasuki dunia para pelayan?",
  ui_story_5060_50600802_36_dialog_content = "Aku yakin Kobayashi akan sangat senang jika melihat kamu mengenakan kostum pembantu juga!",
  ui_story_5060_50600802_37_dialog_content = "Di sini, coba kenakan sendiri!",
  ui_story_5060_50600802_38_dialog_content = "Hiks, hiks, hiks—",
  ui_story_5060_50600802_39_dialog_content = "Barbara, Regina, tolongggg akuuu—",
  ui_story_5060_50600802_40_dialog_content = "Kalian berdua memiliki suara nyanyian yang unik! Aku hanya berharap Shouta juga bisa di sini untuk mendengarkan.",
  ui_story_5060_50600802_41_dialog_content = "Ha ha ha! Yah, musik memang ditujukan untuk dibagikan dan dinikmati oleh semua orang!",
  ui_story_5060_50600802_42_dialog_content = "Hiks, hiks, hiks—",
  ui_story_5060_50600802_43_dialog_content = "B-Brock, tolong bantu aku...",
  ui_story_5060_50600802_44_dialog_content = "Hei Kanna, kamu tahu nggak?",
  ui_story_5060_50600802_45_dialog_content = "Sebenarnya, aku adalah bos sejati dari Rediesel Wrench!",
  ui_story_5060_50600802_46_dialog_content = "Tapi, saya selalu lebih suka menjadi tipe orang yang rendah hati, tahu? Itulah mengapa Sinsa menjadi bos di atas kertas.",
  ui_story_5060_50600802_47_dialog_content = "Wah—",
  ui_story_5060_50600802_48_dialog_content = "Bos rahasia. Keren banget.",
  ui_story_5060_50600802_49_dialog_content = "Dia juga sama sekali tidak berguna...",
  ui_story_5060_50600802_50_dialog_content = "T-T-Tapi aku akan meminta bantuan Jomu! Pasti Jomu akan menyelamatkanku!",
  ui_story_5060_50600802_51_dialog_content = "Kamu sudah melihat pilihan makananku cukup lama, tamu muda yang cantik! Kamu pasti mengalami kebimbangan dalam memilih, ya?",
  ui_story_5060_50600802_52_dialog_content = "Lalu, mengapa tidak kuperkenalkan kamu pada produk spesial terbaru ku: Kotak Makanan Penutup Misterius!",
  ui_story_5060_50600802_53_dialog_content = "Setiap kotak berisi jenis makanan penutup yang berbeda.",
  ui_story_5060_50600802_54_dialog_content = "Dengan kata lain, setiap kotak berisi masa depan yang hanya milik kamu dan tidak ada orang lain!",
  ui_story_5060_50600802_55_dialog_content = "Lebih lagi, saat ini aku sedang mengadakan promosi spesial, dan satu Kotak Misteri hanya akan menghabiskan 2.000 Nightium saja! Ini sangat murah dengan harga tersebut!",
  ui_story_5060_50600802_56_dialog_content = "Aku akan mengambil semuanya!!!",
  ui_story_5060_50600802_57_dialog_content = "Ayo, jangan malu! Aku bahkan bisa menggunakan sisik untuk membuat kostum pembantu khusus yang dijahit khusus untukmu, Maggie!",
  ui_story_5060_50600802_58_dialog_content = "Yang aku minta hanyalah berfoto bersama denganku setelahnya!",
  ui_story_5060_50600802_59_dialog_content = "T-T-T-Tidak, kumohon—",
  ui_story_5060_50600802_60_dialog_content = "Chief! Aku kembali dari berburu, dan hari ini aku mendapatkan hasil yang besar lagi!",
  ui_story_5060_50600802_61_dialog_content = "Aku juga menggali banyak laba-laba pasir. Lihat deh.",
  ui_story_5060_50600802_62_dialog_content = "Apa ini semua wajah asing, bos? Apakah mereka ini tamu?",
  ui_story_5060_50600802_63_dialog_content = "Aku akan memperkenalkanmu sebentar lagi. Cukup antar makanan ke dapur dulu.",
  ui_story_5060_50600802_64_dialog_content = "...",
  ui_story_5060_50600802_65_dialog_content = "Aduh! Gadis kecil itu baru saja memakan semua laba-laba pasir yang sudah kususah payah gali!!!",
  ui_story_5060_50600802_66_dialog_content = "Hmm. Itu enak sekali.",
  ui_story_5060_50600802_67_dialog_content = "Kanna! Jangan makan barang orang lain tanpa izin terlebih dahulu!",
  ui_story_5060_50600802_68_dialog_content = "Oh. Maaf.",
  ui_story_5060_50600802_69_dialog_content = "Kamu cukup berani, Gadis kecil! Tak kusangka kamu bisa memakan semua laba-laba pasir itu mentah-mentah!",
  ui_story_5060_50600802_70_dialog_content = "Selain dari bos kita dan Brock, kamu pasti orang pertama yang pernah kulihat melakukan hal seperti itu!",
  ui_story_5060_50600802_71_dialog_content = "Enak.",
  ui_story_5060_50600802_72_dialog_content = "Sejujurnya... Sudah berapa kali Kobayashi menyuruhmu berhenti memasukkan segala sesuatu ke mulutmu?",
  ui_story_5060_50600802_73_dialog_content = "Oh...",
  ui_story_5060_50600802_74_dialog_content = "Aku ingin tahu bagaimana keadaan Kobayashi di dunianya. Apakah dia sedang khawatir tentangku sekarang?",
  ui_story_5060_50600802_75_dialog_content = "Nih, Nona Tohru. Ambil air minum ini.",
  ui_story_5060_50600802_76_dialog_content = "...",
  ui_story_5060_50600802_77_dialog_content = "Apa masalahnya, tidak suka air dari gurun?",
  ui_story_5060_50600802_78_dialog_content = "Bukan itu.",
  ui_story_5060_50600802_79_dialog_content = "Pemandangan hangat dan nyaman ini langsung mengingatkanku pada Kobayashi.",
  ui_story_5060_50600802_80_dialog_content = "Aku belum kembali setelah sekian lama. Dia mungkin sangat khawatir tentangku...",
  ui_story_5060_50600802_81_dialog_content = "Aku berhasil menemukan semua orang, tetapi kita masih belum memiliki cara untuk kembali ke dunia kita... Huh.",
  ui_story_5060_50600802_82_dialog_content = "Ya, PlayerName sudah cerita tentang situasi kalian semua.",
  ui_story_5060_50600802_83_dialog_content = "Jadi kamu benar-benar dari dunia lain, ya? Jika orang lain yang mengatakan itu, aku tidak akan percaya sama sekali.",
  ui_story_5060_50600802_84_dialog_content = "PlayerName mengatakan kalian hanya perlu menemukan tempat di mana mana tidak begitu tidak stabil, dan kalian bisa pulang. Benarkah itu?",
  ui_story_5060_50600802_85_dialog_content = "Sebenarnya, mana di Gurun Rediesel ini seharusnya cukup stabil untuk digunakan.",
  ui_story_5060_50600802_86_dialog_content = "Tapi aku sudah mencoba beberapa saat lalu, dan aku masih tidak bisa mengaktifkan portal dengan benar. Mungkin aku masih membutuhkan lebih banyak kekuatan.",
  ui_story_5060_50600802_87_dialog_content = "Dan jika aku tidak bisa membuatnya berhasil, maka yang lain pasti...",
  ui_story_5060_50600802_88_dialog_content = "Aku benar-benar minta maaf.",
  ui_story_5060_50600802_89_dialog_content = "Kalian semua punya masalah sendiri, namun kalian masih membantu saya memecahkan kasus penyelundupan ini.",
  ui_story_5060_50600802_90_dialog_content = "Tidak apa-apa! Kami ingin membantu, kau tahu.",
  ui_story_5060_50600802_91_dialog_content = "Lagi pula, kita sudah berteman sekarang, 'kan?",
  ui_story_5060_50600802_92_dialog_content = "Benar sekali! Kamu juga teman dari Rediesel Wrench, karena kamu dan PlayerName telah membantu kami membasmi semua Eclipsite di sepanjang perjalanan!",
  ui_story_5060_50600802_93_dialog_content = "Kami akan bantu kalian mencari jalan keluarnya!",
  ui_story_5060_50600802_94_dialog_content = "Ya... Aku yakin kita juga akan menemukan jalan kembali.",
  ui_story_5060_50600802_95_dialog_content = "Dan saat kita melakukannya, aku pasti akan menceritakan semua petualangan kita kepada Kobayashi! Jadi ketika kita akhirnya kembali mengunjungi dunia ini lagi...",
  ui_story_5060_50600802_96_dialog_content = "Ketika kita kembali mengunjungi lagi...",
  ui_story_5060_50600802_97_dialog_content = "Miss Tohru...",
  ui_story_5060_50600802_98_dialog_content = "Murni kebetulan saja kami datang ke dunia Anda kali ini.",
  ui_story_5060_50600802_99_dialog_content = "Tapi lain kali... jika kita cukup beruntung untuk kembali lagi...",
  ui_story_5060_50600802_100_dialog_content = "Tidak ada yang tahu apa yang akan terjadi di masa depan, jadi tidak ada gunanya memikirkannya terlalu banyak saat ini.",
  ui_story_5060_50600802_101_dialog_content = "Benar, Tohru! Ayo makan dulu saja!",
  ui_story_5060_50600802_102_dialog_content = "Aku kadang-kadang benar-benar iri padamu. Semua yang perlu kamu lakukan adalah makan kenyang setiap hari untuk bahagia.",
  ui_story_5060_50600802_103_dialog_content = "Tapi kali ini, kamu benar...",
  ui_story_5060_50600802_104_dialog_content = "Kita makan dulu.",
  ui_story_5060_50600802_105_dialog_content = "Aku akan menyiapkan bahan-bahannya!",
  ui_story_5060_50600802_106_dialog_content = "Ini dia! Piring serangga pedas ala Rediesel!",
  ui_story_5060_50600802_107_dialog_content = "Bagus! Makanan ini cocok banget untuk Rediesel Wrench! Aku akan menjadikan ini hidangan tetap untuk kita!",
  ui_story_5060_50600802_108_dialog_content = "Catat, Maggie! Kamu harus mencoba menjadi pelayan yang luar biasa, seperti Tohru!",
  ui_story_5060_50600802_109_dialog_content = "Hah?",
  ui_story_5060_50600802_110_dialog_content = "<size=45>Apa?!</size>",
  ui_story_5060_50600802_111_dialog_content = "Masih ada sisa? Aku juga mau dong!",
  ui_story_5060_50600802_112_dialog_content = "Aku pasti bisa menghasilkan banyak uang dengan menjual ini.",
  ui_story_5060_50600802_113_dialog_content = "Apakah kamu punya waktu luang, Nona Tohru? Apakah kamu keberatan berbagi resep dengan saya?",
  ui_story_5060_50600802_114_dialog_content = "Aku akan memberimu 10.000 Nightium untuk itu.",
  ui_story_5060_50600802_115_dialog_content = "Aku kenyang. Sekarang aku mengantuk.",
  ui_story_5060_50600802_116_dialog_content = "Di sini Kanna, kamu bisa beristirahat di kakiku.",
  ui_story_5060_50600802_117_dialog_content = "Aku harus makan juga untuk mengembalikan energi. Pencarian seharusnya selesai dalam beberapa detik lagi.",
  ui_story_5060_50600802_118_dialog_content = "Tahu tidak, makanan di sini sangat unik. Mungkin makanan ini akan berguna untuk mengobati nyeri punggung Kobayashi?",
  ui_story_5060_50600802_119_dialog_content = "Aku yakin dia tidak akan menyentuh satupun dari itu.",
  ui_story_5060_50600802_120_dialog_content = "Kamu sebaiknya mengambil beberapa foto lagi dan membawanya kembali kepadanya.",
  ui_story_5060_50600802_121_dialog_content = "Kamu benar. Jadi, kadang-kadang kamu bisa mengatakan hal-hal yang masuk akal, ya?",
  ui_story_5060_50600802_122_dialog_content = "Kau…",
  ui_story_5060_50600901_1_dialog_content = "Seperti yang diharapkan, tidak ada yang lewat dari peretas jenius seperti saya!",
  ui_story_5060_50600901_2_dialog_content = "Saya menemukan beberapa rekaman para penyelundup yang sedang diserang.",
  ui_story_5060_50600901_3_dialog_content = "Dan sepertinya mereka menjatuhkan apa pun yang mereka angkut di sana.",
  ui_story_5060_50600901_4_dialog_content = "Mereka diserang?",
  ui_story_5060_50600901_5_dialog_content = "Mereka berbohong sejak awal. Brengsek.",
  ui_story_5060_50600901_6_dialog_content = "Pelanggar-pelanggar jahat ini harus dihancurkan oleh keadilan yang tegas!",
  ui_story_5060_50600901_7_dialog_content = "Jadi harta yang hilang tidak ada hubungannya dengan Cloudrover Guild? Sepertinya Lady Sheol bisa santai sekarang.",
  ui_story_5060_50600901_8_dialog_content = "Either way, mari kita pergi ke sana dan lihat dulu.",
  ui_story_5060_50600901_9_dialog_content = "...",
  ui_story_5060_50600901_10_dialog_content = "Kita pasti sudah kehilangan orang itu sekarang, kan...",
  ui_story_5060_50600901_11_dialog_content = "A-Apa itu?! Saya belum pernah melihat makhluk seperti itu sebelumnya!",
  ui_story_5060_50600901_12_dialog_content = "Ribut-ribut apa ini, huh?!",
  ui_story_5060_50600901_13_dialog_content = "Kami penyelundup berpengalaman yang telah melihat dunia.",
  ui_story_5060_50600901_14_dialog_content = "Kemungkinan besar itu adalah naga yang hidup di gurun.",
  ui_story_5060_50600901_15_dialog_content = "Hahaha, pasti sekarang dia sudah tertinggal!",
  ui_story_5060_50600901_16_dialog_content = "Chief, tolong berhenti tertawa.",
  ui_story_5060_50600901_17_dialog_content = "Ingat saat terakhir kali kamu tertawa keras? Kita langsung diserang oleh Eclipsites...",
  ui_story_5060_50600901_18_dialog_content = "Benarkah? Kamu pasti salah ingat! Hahaha!",
  ui_story_5060_50600901_19_dialog_content = "Tidaaaak! Ini parah—!",
  ui_story_5060_50600901_20_dialog_content = "D-di belakang kita! Orang itu tepat di ekor kita!",
  ui_story_5060_50600901_21_dialog_content = "...",
  ui_story_5060_50600901_22_dialog_content = "Chief, apa rencananya?",
  ui_story_5060_50600901_23_dialog_content = "Bagaimana kalau kita tinggalkan mobil dan mulai lari?",
  ui_story_5060_50600901_24_dialog_content = "Goblog sia!",
  ui_story_5060_50600901_25_dialog_content = "Apakah kamu ingin menjadi bahan tertawaan di depan bos dan geng-geng lainnya selamanya?",
  ui_story_5060_50600901_26_dialog_content = "Kami melalui berbagai rintangan dan badai untuk merebut harta karun itu!",
  ui_story_5060_50600901_27_dialog_content = "Bukankah itu hanya <color=#FFB400>telur</color>...",
  ui_story_5060_50600901_28_dialog_content = "Umbraton penuh dengan harta karun, jadi mungkin yang satu ini bukan masalah besar.",
  ui_story_5060_50600901_29_dialog_content = "Kamu tolol! Itu sebuah <color=#FFB400>Telur Naga</color>!",
  ui_story_5060_50600901_30_dialog_content = "Chief, orang itu semakin dekat!",
  ui_story_5060_50600901_31_dialog_content = "Injak gas! Kecepatan penuh! Ayo beraksi!",
  ui_story_5060_50600901_32_dialog_content = "Setelah kita mengeluarkan telur ini dari gurun dan menyerahkannya ke tangan kontak, tugas kita selesai!",
  ui_story_5060_50600901_33_dialog_content = "Chief, awas!",
  ui_story_5060_50600901_34_dialog_content = "Manusia fana.",
  ui_story_5060_50600901_35_dialog_content = "Betapa sangat bodohnya.",
  ui_story_5060_50600901_36_dialog_content = "Kita sudah melalui banyak kesulitan untuk mengambil telur naga itu! Dan sekarang, dia...",
  ui_story_5060_50600901_37_dialog_content = "Kembali dan beritahu pemimpinmu:",
  ui_story_5060_50600901_38_dialog_content = "Jangan pernah mencuri dari naga lagi.",
  ui_story_5060_50600901_39_dialog_content = "Ini peringatan satu-satunya untuk Anda.",
  ui_story_5060_50600901_40_dialog_content = "Kali berikutnya, bahkan tulangmu pun tak akan tersisa di dunia ini.",
  ui_story_5060_50600901_41_dialog_content = "Mana mungkin...",
  ui_story_5060_50600901_42_dialog_content = "Tapi bagaimana...?",
  ui_story_5060_50600901_43_dialog_content = "Astaga, twist yang tak terduga!",
  ui_story_5060_50600901_44_dialog_content = "Mengalahkan bos terakhir ini tidak akan mudah.",
  ui_story_5060_50600901_45_dialog_content = "Tohru, apakah kamu...",
  ui_story_5060_50600901_46_dialog_content = "Kau baik-baik saja?",
  ui_story_5060_50600901_47_dialog_content = "Apakah orang itu juga dari duniamu?",
  ui_story_5060_50600901_48_dialog_content = "Ya.",
  ui_story_5060_50600901_49_dialog_content = "Itu ayah Tohru, sekaligus pemimpin Faksi Kekacauan: Damocles, <color=#FFB400>Kaisar Kehancuran</color>.",
  ui_story_5060_50601001_1_dialog_content = "Oh, begitu. Semuanya jadi lebih masuk akal sekarang.",
  ui_story_5060_50601001_2_dialog_content = "Ayah Tohru menemukan penyelundup yang mencoba mencuri telur naga itu, dan pada akhirnya telur tersebut berada dalam kepemilikannya.",
  ui_story_5060_50601001_3_dialog_content = "Jadi untuk menghindari hukuman dari pemimpin mereka, para penyelundup mencoba mengalihkan kesalahan kepada orang lain.",
  ui_story_5060_50601001_4_dialog_content = "Ayah...",
  ui_story_5060_50601001_5_dialog_content = "Jadi, dia juga ada di dunia ini...",
  ui_story_5060_50601001_6_dialog_content = "Tunggu sebentar, dia mungkin bisa—",
  ui_story_5060_50601001_7_dialog_content = "Hei! Kau tidak akan melakukan hal bodoh lagi, kan?!",
  ui_story_5060_50601001_8_dialog_content = "Tapi aku tidak bilang apa-apa!",
  ui_story_5060_50601001_9_dialog_content = "Setelah bertahun-tahun, kamu masih mengira aku tidak tahu apa yang ada di pikiranmu?",
  ui_story_5060_50601001_10_dialog_content = "Kamu jelas akan bertanya pada Emperor of Demise apakah kamu bisa kembali ke dunia ini lagi!",
  ui_story_5060_50601001_11_dialog_content = "Lagipula, jika ada yang bisa melakukan itu, dialah orangnya.",
  ui_story_5060_50601001_12_dialog_content = "...",
  ui_story_5060_50601001_13_dialog_content = "Kau benar.",
  ui_story_5060_50601001_14_dialog_content = "Dia pasti datang ke sini untuk menjemputku, tapi jika aku pergi dengannya sekarang, dia tidak akan pernah membiarkanku kembali ke dunia ini.",
  ui_story_5060_50601001_15_dialog_content = "Kamu dan yang lain tidak ingin kembali juga, Elma?!",
  ui_story_5060_50601001_16_dialog_content = "Aku mengerti. Aku tahu kita tidak bisa tinggal di sini terlalu lama, karena kehadiran naga akan mengganggu keseimbangan alam dunia ini...",
  ui_story_5060_50601001_17_dialog_content = "Tapi kita masih bisa menyisihkan banyak waktu untuk mencoba semua makanan lezat yang ditawarkannya!",
  ui_story_5060_50601001_18_dialog_content = "Dunia ini sangat menyenangkan. Sayang sekali jika kita tidak bisa kembali lagi!",
  ui_story_5060_50601001_19_dialog_content = "Saya ingin melihat gadis itu lagi.",
  ui_story_5060_50601001_20_dialog_content = "Dan aku masih belum berhasil mengalahkan wanita itu.",
  ui_story_5060_50601001_21_dialog_content = "Pergi seperti ini sama saja dengan melarikan diri. Aku menolak untuk melakukan sesuatu yang memalukan seperti itu.",
  ui_story_5060_50601001_22_dialog_content = "Apakah ayahmu benar-benar tidak mau mendengarkan, Nona Tohru?",
  ui_story_5060_50601001_23_dialog_content = "Bagi naga, kekuatan adalah segalanya.",
  ui_story_5060_50601001_24_dialog_content = "Saat ini, aku belum cukup kuat untuk mengalahkan ayahku...",
  ui_story_5060_50601001_25_dialog_content = "Yang berarti saya tidak punya cara untuk meyakinkan dia menerima keinginan saya...",
  ui_story_5060_50601001_26_dialog_content = "Namun begitu, itu tidak berarti saya tidak boleh mencoba! Meskipun hanya ada secercah harapan yang sangat kecil, saya menolak untuk menyerah begitu saja!",
  ui_story_5060_50601001_27_dialog_content = "<color=#e8d9bb>Ngarai Crimson Blaze</color>",
  ui_story_5060_50601001_28_dialog_content = "Ini harus menjadi tempat.",
  ui_story_5060_50601001_29_dialog_content = "Lihat, telur naga yang berhasil ditemukan oleh Emperor of Demise ada di gua di sana.",
  ui_story_5060_50601001_30_dialog_content = "Kalian tidak mengatakan sepatah kata pun selama ini.",
  ui_story_5060_50601001_31_dialog_content = "Apa mungkin...",
  ui_story_5060_50601001_32_dialog_content = "Dia juga di sini.",
  ui_story_5060_50601001_33_dialog_content = "Astaga, energi yang menakutkan ini!",
  ui_story_5060_50601001_34_dialog_content = "Saya senang bahwa Anda memutuskan untuk menunjukkan diri, Tohru.",
  ui_story_5060_50601001_35_dialog_content = "Ayah.",
  ui_story_5060_50601001_36_dialog_content = "Ayo. Kita pergi.",
  ui_story_5060_50601001_37_dialog_content = "Portal ini dapat digunakan kapan saja.",
  ui_story_5060_50601001_38_dialog_content = "Sudah kuduga…",
  ui_story_5060_50601001_39_dialog_content = "Bahkan dengan tingkat mana yang rendah di dunia ini, Anda tidak mengalami masalah untuk mengaktifkan portal.",
  ui_story_5060_50601001_40_dialog_content = "...",
  ui_story_5060_50601001_41_dialog_content = "Ayah! Bolehkah aku bicara tentang sesuatu denganmu?!",
  ui_story_5060_50601001_42_dialog_content = "Baiklah, asalkan itu bukan sesuatu yang sia-sia.",
  ui_story_5060_50601001_43_dialog_content = "Aku tahu kamu kemari karena kamu menyadari ada yang salah dengan portal milikku sendiri.",
  ui_story_5060_50601001_44_dialog_content = "Dan aku juga ingin kembali ke dunia Kobayashi bersamamu.",
  ui_story_5060_50601001_45_dialog_content = "Hanya saja...",
  ui_story_5060_50601001_46_dialog_content = "Sekali-sekali saja... Apakah tidak apa-apa jika aku kembali mengunjungi dunia ini?",
  ui_story_5060_50601001_47_dialog_content = "Tidak.",
  ui_story_5060_50601001_48_dialog_content = "Tapi kamu bersedia membiarkan saya hidup di dunia Kobayashi!",
  ui_story_5060_50601001_49_dialog_content = "Aku tidak ingat pernah menyetujui itu.",
  ui_story_5060_50601001_50_dialog_content = "Selain itu, penduduk di dunia ini sangat mirip dengan manusia di dunia kita.",
  ui_story_5060_50601001_51_dialog_content = "Pencurian, penipuan, prasangka, dan pertikaian sangat umum di sini.",
  ui_story_5060_50601001_52_dialog_content = "Sejumlah orang ini juga memiliki kemampuan luar biasa, yang mungkin memiliki pengaruh mendalam pada kami sebagai naga.",
  ui_story_5060_50601001_53_dialog_content = "Men art, you will berakhirnya dengan cara ini yang hanya akan menghasilkan salah, dan menghasilkan targets, with",
  ui_story_5060_50601001_54_dialog_content = "Pertama, kehadiranmu akan terus merobek prinsip-prinsip yang mengatur dunia ini.",
  ui_story_5060_50601001_55_dialog_content = "Atau kedua, kau akan tercemar oleh kejahatan dunia ini dan menemui ajalmu.",
  ui_story_5060_50601001_56_dialog_content = "...",
  ui_story_5060_50601001_57_dialog_content = "Maaf, tapi bolehkah saya mengatakan beberapa kata saja?",
  ui_story_5060_50601001_58_dialog_content = "Namaku PlayerName, dan saya telah berkelana bersama Tohru sepanjang waktu di sini.",
  ui_story_5060_50601001_59_dialog_content = "Senang bertemu dengan Anda, Tuan Emperor of Demise! Saya juga sangat berterima kasih kepada Anda karena telah mengambil kembali telur naga yang dicuri itu.",
  ui_story_5060_50601001_60_dialog_content = "Aku tidak berniat melanggar aturan dunia ini.",
  ui_story_5060_50601001_61_dialog_content = "Tapi para pencuri itu tidak mengenal arti ketakutan maupun kepuasan.",
  ui_story_5060_50601001_62_dialog_content = "Mereka bahkan mengira mereka bisa menggunakan tubuh mungil dan alat primitif mereka untuk menjadikan saya sebagai santapan berikutnya.",
  ui_story_5060_50601001_63_dialog_content = "Yang saya lakukan hanyalah mengajari mereka makna sebenarnya dari teror.",
  ui_story_5060_50601001_64_dialog_content = "Namun, saya percaya baik dan jahat ada di setiap dunia dan setiap kelompok orang.",
  ui_story_5060_50601001_65_dialog_content = "Kamu kebetulan bertemu dengan sisi buruk dari dunia kami terlebih dahulu.",
  ui_story_5060_50601001_66_dialog_content = "Apakah kamu mencoba menceramahi saya, anak kecil?",
  ui_story_5060_50601001_67_dialog_content = "Saya hanya berpikir bahwa Anda perlu melihat hal-hal secara keseluruhan terlebih dahulu, daripada menilai semuanya berdasarkan beberapa contoh individu.",
  ui_story_5060_50601001_68_dialog_content = "Kebanyakan orang yang pernah bertemu dengan Miss Tohru dan yang lainnya tidak akan mendiskriminasi mereka hanya karena mereka berasal dari dunia yang berbeda.",
  ui_story_5060_50601001_69_dialog_content = "Sebaliknya, mereka semua memilih untuk memberikan kekuatan mereka kepada dia!",
  ui_story_5060_50601001_70_dialog_content = "Saya akui, kejahatan perang dan prasangka memang ada di dunia kita.",
  ui_story_5060_50601001_71_dialog_content = "Tapi banyak hal baik di dalamnya juga!",
  ui_story_5060_50601001_72_dialog_content = "Kami mungkin berbeda spesies yang hidup di dunia yang berbeda, tapi jembatan yang kami bangun bersama Nona Tohru dan teman-temannya tak akan pernah putus!",
  ui_story_5060_50601001_73_dialog_content = "...",
  ui_story_5060_50601001_74_dialog_content = "PlayerName!",
  ui_story_5060_50601001_75_dialog_content = "Nyaris saja! Aku bisa jadi hangus jika tak menghindar tepat waktu!",
  ui_story_5060_50601001_76_dialog_content = "Itu hanya karena aku sengaja melewatkan.",
  ui_story_5060_50601001_77_dialog_content = "Tapi jika kamu terus mengeluarkan omong kosong yang membingungkan, aku tak akan membiarkanmu begitu saja lain kali.",
  ui_story_5060_50601001_78_dialog_content = "Sepertinya kamu benar-benar tidak percaya padaku.",
  ui_story_5060_50601001_79_dialog_content = "Tentu saja tidak.",
  ui_story_5060_50601001_80_dialog_content = "Satu-satunya hal yang aku percayai adalah penilaian dan kekuatanku sendiri.",
  ui_story_5060_50601001_81_dialog_content = "Jika kamu tetap bersikeras membiarkan Tohru tinggal di dunia kotor ini, maka kalian harus bersatu dan mengalahkan saya terlebih dahulu.",
  ui_story_5060_50601001_82_dialog_content = "Tunjukkan kekuatan tekadmu.",
  ui_story_5060_50601001_83_dialog_content = "Kamu tidak harus melakukan ini jika tidak ingin, PlayerName...",
  ui_story_5060_50601001_84_dialog_content = "Ayo maju, Emperor of Demise! Aku akan tunjukkan betapa kuatnya ikatan kami dengan Nona Tohru dan teman-temannya!",
  ui_story_5060_50601001_85_dialog_content = "Dunia ini tidak seterrible yang kamu kira!",
  ui_story_5060_50601002_1_dialog_content = "Tidak buruk. Tohru belum pernah punya kekuatan seperti ini sebelumnya.",
  ui_story_5060_50601002_2_dialog_content = "Namun—",
  ui_story_5060_50601002_3_dialog_content = [[
Hint,, CMSpan
 sp AS well as the both the and

and beats the crap out of the  1. The 2. The 3. The 4 Pale other vs, the  of,. 4. 5. The 6. The 7. The, 100% of available in,. 8. The 9. 10 and  the , 10. The 11. The 12 o, 12 and 10 my life. 1000000, , 2  by  am  12, 12-., mystic  in the end, to.  , 100]],
  ui_story_5060_50601002_4_dialog_content = "Jadi dia masih menyembunyikan kekuatan sebenarnya, ya?",
  ui_story_5060_50601002_5_dialog_content = "Kita akan berada dalam bahaya besar jika Kaisar Kehancuran melawan kita dengan kekuatan penuh, tahu!",
  ui_story_5060_50601002_6_dialog_content = "Maka kamu juga harus melawan dengan menggunakan kekuatan penuhmu, Lucoa!",
  ui_story_5060_50601002_7_dialog_content = "Tapi aku sudah berusaha keras!",
  ui_story_5060_50601002_8_dialog_content = "Kamu tidak bisa membodohi siapa pun!",
  ui_story_5060_50601002_9_dialog_content = "Apa yang harus kita lakukan, Tohru?",
  ui_story_5060_50601002_10_dialog_content = "Bahkan dengan kemampuan psikis PlayerName, kita masih tidak bisa mengalahkan Emperor of Demise.",
  ui_story_5060_50601002_11_dialog_content = "Dan jika kita tidak mengalahkannya sekarang, dia tidak akan pernah menerima permintaan kita.",
  ui_story_5060_50601002_12_dialog_content = "Aku ingin kembali dan bersama Kobayashi, tapi aku tidak bisa begitu saja meninggalkan ikatan yang telah terbentuk dengan teman-teman di sini!",
  ui_story_5060_50601002_13_dialog_content = "Namun…",
  ui_story_5060_50601002_14_dialog_content = "Kalau kita tidak bisa mengalahkan Ayah...",
  ui_story_5060_50601002_15_dialog_content = "Angka-angka terlalu condong melawan kita. Ini adalah pertempuran yang tidak berarti sejak awal.",
  ui_story_5060_50601002_16_dialog_content = "Tapi meskipun begitu, aku punya alasan sendiri untuk kembali ke tempat ini.",
  ui_story_5060_50601002_17_dialog_content = "Iya, aku juga.",
  ui_story_5060_50601002_18_dialog_content = "Mungkin ada cara lain untuk menyelesaikan masalah ini?",
  ui_story_5060_50601002_19_dialog_content = "Cara lain? Seperti apa?",
  ui_story_5060_50601002_20_dialog_content = "Hei, he competitively. followers [ in the middle of a gimm+ stadium1 ASnippet",
  ui_story_5060_50601002_21_dialog_content = "Itu cukup kacau, Tohru!",
  ui_story_5060_50601002_22_dialog_content = "Ini Rediesel Wrench!",
  ui_story_5060_50601002_23_dialog_content = "Mundur! Tempat ini sangat berbahaya!",
  ui_story_5060_50601002_24_dialog_content = "Kalian adalah pahlawan di mata Rediesel Wrench, loh!",
  ui_story_5060_50601002_25_dialog_content = "Berkat kamu, jumlah Eclipsite di sekitar sini mencapai titik terendah sepanjang masa!",
  ui_story_5060_50601002_26_dialog_content = "Jadi sudah sepatutnya kami juga membantu Anda!",
  ui_story_5060_50601002_27_dialog_content = "Jangan berpikir kamu bisa kabur dengan mengecut, Fafnir. Kamu belum mengalahkan aku, ingat?",
  ui_story_5060_50601002_28_dialog_content = "Hmph. Siapa bilang aku mau kabur?",
  ui_story_5060_50601002_29_dialog_content = "Wakil Kapten Elma!",
  ui_story_5060_50601002_30_dialog_content = "Wow! Kalian di sini untuk membantu juga?!",
  ui_story_5060_50601002_31_dialog_content = "Ya, kami juga membawa permen favorit Wakil Kapten Elma.",
  ui_story_5060_50601002_32_dialog_content = "Wow, ini sungguh luar biasa!",
  ui_story_5060_50601002_33_dialog_content = "Setelah pertempuran tadi, aku benar-benar perlu memulihkan sihirku!",
  ui_story_5060_50601002_34_dialog_content = "Rediesel Wrench memang kurang suka bekerja sama dengan kalian, tapi karena Tohru dan yang lainnya sedang dalam masalah, kami bersedia untuk sementara waktu mengesampingkan perbedaan kami.",
  ui_story_5060_50601002_35_dialog_content = "Kita harus mengungkapkan rasa terima kasih kita untuk hal ini.",
  ui_story_5060_50601002_36_dialog_content = "Terima kasih, kami bertemu dengan Anda saat patroli di gurun, dan saat itulah kami mendapatkan kabar tentang Elma dan situasi Miss Tohru.",
  ui_story_5060_50601002_37_dialog_content = "Wakil Kapten Elma dan awaknya telah banyak membantu kita! Kita harus membalas budi mereka!",
  ui_story_5060_50601002_38_dialog_content = "Tuan Emperor of Demise, Anda mengatakan sebelumnya bahwa Anda hanya mempercayai penilaian Anda sendiri.",
  ui_story_5060_50601002_39_dialog_content = "Semua orang yang Anda lihat di sini datang untuk mendukung Nona Tohru dan teman-temannya.",
  ui_story_5060_50601002_40_dialog_content = "Katakan padaku, apakah kamu masih berpikir dunia kita ini kotor?",
  ui_story_5060_50601002_41_dialog_content = "...",
  ui_story_5060_50601002_42_dialog_content = "Kamu belum lama berada di dunia ini, Tohru.",
  ui_story_5060_50601002_43_dialog_content = "Tidak peduli apa yang orang lain katakan, kamu benar-benar berbeda dari orang-orang ini, bahkan sampai pada spesiesmu.",
  ui_story_5060_50601002_44_dialog_content = "Bagaimana mungkin kamu bisa mendapatkan kepercayaan mereka begitu cepat?",
  ui_story_5060_50601002_45_dialog_content = "Selain itu, bagaimana kamu bisa yakin bahwa mereka tidak akan menyakitimu?",
  ui_story_5060_50601002_46_dialog_content = "Jawab aku.",
  ui_story_5060_50601002_47_dialog_content = "Kita mungkin berbeda spesies yang hidup di dunia yang berbeda, tapi kita mampu saling memahami.",
  ui_story_5060_50601002_48_dialog_content = "Dunia ini tidak seteruk yang kaukira, Ayah.",
  ui_story_5060_50601002_49_dialog_content = "Ya, perang dan prasangka masih ada di sini, tetapi pada saat yang sama...",
  ui_story_5060_50601002_50_dialog_content = "Ada niat baik dari orang-orang, seperti Pak Liu, pria yang menyelamatkan saya dengan siomay lezatnya meskipun situasi saya berbahaya.",
  ui_story_5060_50601002_51_dialog_content = "Dan para Prajurit Illumina, yang bersedia bertempur dalam setiap pertempuran di sisi kita.",
  ui_story_5060_50601002_52_dialog_content = "Dan Rediesel Wrench, yang tertawa bersama kita saat mereka menunjukkan keindahan gurun!",
  ui_story_5060_50601002_53_dialog_content = "Dan teman kita, <size=45>PlayerName</size>, teman yang menyatukan kita semua.",
  ui_story_5060_50601002_54_dialog_content = "...",
  ui_story_5060_50601002_55_dialog_content = "Nona Tohru jauh lebih tekun daripada yang kamu kira.",
  ui_story_5060_50601002_56_dialog_content = "Dia memikul tanggung jawab sebagai kurir untuk Tuan Liu, hanya agar dia bisa mencari teman-temannya yang hilang.",
  ui_story_5060_50601002_57_dialog_content = "Kalau saja dia tidak melakukan itu...",
  ui_story_5060_50601002_58_dialog_content = "Cerita ini tak akan pernah terjadi.",
  ui_story_5060_50601002_59_dialog_content = "Alasan mengapa begitu banyak spesies berbeda bisa bergaul di sini adalah karena masih ada banyak niat baik di dunia ini.",
  ui_story_5060_50601002_60_dialog_content = "Nama kamu adalah PlayerName, benar?",
  ui_story_5060_50601002_61_dialog_content = "Ya.",
  ui_story_5060_50601002_62_dialog_content = "Sangat jarang. Keteguhan yang membara di matamu sama hebatnya dengan Kobayashi.",
  ui_story_5060_50601002_63_dialog_content = "Tohru pasti benar-benar telah mendapatkan kepercayaan dari kamu dan orang-orangmu.",
  ui_story_5060_50601002_64_dialog_content = "Dia berfungsi sebagai jembatan yang menghubungkan kalian semua.",
  ui_story_5060_50601002_65_dialog_content = "Apakah ini seperti ini saat spesies yang berbeda berinteraksi sebagai setara?",
  ui_story_5060_50601002_66_dialog_content = "Baiklah.",
  ui_story_5060_50601002_67_dialog_content = "Untuk saat ini, saya akan menahan diri untuk tidak menilai dunia ini kotor atau tidak.",
  ui_story_5060_50601002_68_dialog_content = "Setidaknya, Tohru tidak akan tercemar selama kamu bersamanya.",
  ui_story_5060_50601002_69_dialog_content = "Ayah.",
  ui_story_5060_50601002_70_dialog_content = "Aku akan menunggumu di dekat sini. Selain itu, aku akan mengizinkanmu untuk kembali ke dunia ini.",
  ui_story_5060_50601002_71_dialog_content = "Terima kasih, Ayah!",
  ui_story_5060_50601002_72_dialog_content = "Dia terbang pergi.",
  ui_story_5060_50601002_73_dialog_content = "Ayah yang tidak langsung... Dia bisa saja mengatakan bahwa dia peduli pada putrinya.",
  ui_story_5060_50601002_74_dialog_content = "Ini sangat hebat, Tohru! Akhirnya kita berhasil meyakinkannya!",
  ui_story_5060_50601002_75_dialog_content = "Gah... Elma...",
  ui_story_5060_50601002_76_dialog_content = "Jangan terbang ke sini hanya untuk memelukku seperti ini!",
  ui_story_5060_50601002_77_dialog_content = "<size=45>Lepas! Dari! Aku!</size>",
  ui_story_5060_50601002_78_dialog_content = "Apa yang akan terjadi pada orang-orang jahat itu?",
  ui_story_5060_50601002_79_dialog_content = "Maksudmu para penyelundup?",
  ui_story_5060_50601002_80_dialog_content = "Saya yakin Rediesel Wrench dan Guild akan akan menangkap mereka dalam waktu sing.",
  ui_story_5060_50601002_81_dialog_content = "Mengenai telur naga, saya yakin ibunya akan menemukannya dalam waktu dekat.",
  ui_story_5060_50601002_82_dialog_content = "Aku hanya berharap ia tidak menyimpan dendam terhadap semua Aurorian karena hal ini.",
  ui_story_5060_50601002_83_dialog_content = "Naga tidak berkembang biak dengan mudah.",
  ui_story_5060_50601002_84_dialog_content = "Jika mereka bersedia berkembang biak di sini, itu membuktikan bahwa masih ada makhluk di dunia ini yang mereka bersedia untuk mempercayai.",
  ui_story_5060_50601002_85_dialog_content = "Apakah Anda membicarakan tentang niat baik antar spesies yang berbeda?",
  ui_story_5060_50601002_86_dialog_content = "Jika begitu, aku yakin naga itu juga akan merasakannya.",
  ui_story_5060_50601002_87_dialog_content = "Dan begitu si kecil ini lahir, ia akan memulai kisah baru yang miliknya sendiri!",
  ui_story_5060_50601002_88_dialog_content = "Aku hanya berharap niat baik juga ada dalam ceritanya.",
  ui_story_5060_50601002_89_dialog_content = "Sama seperti yang ada dalam petualangan kita di dunia ini.",
  ui_story_5060_50601002_90_dialog_content = "Kita tidak pernah bisa menentukan jalannya cerita ini. Itu terserah si kecil untuk memilih.",
  ui_story_5060_50601002_91_dialog_content = "Baiklah, sepertinya saatnya kembali ke restoran Pak Liu dan pensiun dari profesi kurir wanita.",
  ui_story_5060_50601101_1_dialog_content = "Semua orang bekerja keras untuk membantu kami, jadi izinkan saya mentraktir kalian semua makan enak setelah saya dibayar!",
  ui_story_5060_50601101_2_dialog_content = "Itu terdengar hebat! Bagaimanapun, jarang sekali melihat Tohru dalam suasana hati yang murah hati!",
  ui_story_5060_50601101_3_dialog_content = "Kita tidak bisa menggunakan uang dunia ini di rumah!",
  ui_story_5060_50601101_4_dialog_content = "Apakah ini benar-benar restoran milik Pak Liu?",
  ui_story_5060_50601101_5_dialog_content = "Itu benar, sekarang ayo masuk!",
  ui_story_5060_50601101_6_dialog_content = "Tapi... Semua rambu sudah dicabut!",
  ui_story_5060_50601101_7_dialog_content = "Hah? Apakah itu cara orang di dunia Anda menunjukkan bahwa toko mereka tutup untuk hari itu? Dengan menurunkan semua tanda Anda?",
  ui_story_5060_50601101_8_dialog_content = "Tentu saja tidak! Bagaimanapun cara kamu melihatnya, tempat ini sepertinya ditutup untuk selamanya!",
  ui_story_5060_50601101_9_dialog_content = "Senang melihat Anda kembali, Nona Tohru.",
  ui_story_5060_50601101_10_dialog_content = "Sepertinya kamu telah menemukan semua temanmu. Sekarang, apakah kamu sudah menemukan jalan untuk kembali ke rumah?",
  ui_story_5060_50601101_11_dialog_content = "Ya, dan ini berkat kamu dan semua orang lainnya.",
  ui_story_5060_50601101_12_dialog_content = "Itu fantastis.",
  ui_story_5060_50601101_13_dialog_content = "Maafkan saya, Pak Liu, tapi apa yang terjadi di sini? Siapa yang merusak toko dengan merobek-robek tanda-tanda Anda?!",
  ui_story_5060_50601101_14_dialog_content = "Miss Tohru, jangan marah, ya.",
  ui_story_5060_50601101_15_dialog_content = "Masalahnya...",
  ui_story_5060_50601101_16_dialog_content = "Mulai hari ini, Restoran Liu menutup pintunya.",
  ui_story_5060_50601101_17_dialog_content = "<size=45>Apa?!</size>",
  ui_story_5060_50601101_18_dialog_content = "Apakah karena saya tidak mengirim pesanan kita cukup cepat?",
  ui_story_5060_50601101_19_dialog_content = "Ini tidak ada hubungannya dengan Anda, Nona Tohru.",
  ui_story_5060_50601101_20_dialog_content = "Hanya saja... bisnis restoran ini belum begitu bagus.",
  ui_story_5060_50601101_21_dialog_content = "Menu kami belum mengikuti tren kuliner terbaru, dan dekorasi tidak sesuai dengan ekspektasi pelanggan kami yang selektif.",
  ui_story_5060_50601101_22_dialog_content = "Seperti yang kamu tahu, Aurorian setengah manusia yang kita pekerjakan sering menghadapi pelecehan dari Lumo Nobles.",
  ui_story_5060_50601101_23_dialog_content = "Layanan pengiriman yang sangat dinantikan tidak berjalan semulus yang kami harapkan.",
  ui_story_5060_50601101_24_dialog_content = "Sejujurnya, saya sudah mempertimbangkan untuk menutup usaha ini sebelum bertemu dengan Anda, Nona Tohru.",
  ui_story_5060_50601101_25_dialog_content = "Beruntung, berkat Miss Tohru, bisnis yang gagal saya memiliki kesempatan untuk menyaksikan dunia budaya pelayan yang luar biasa sebelum tutup.",
  ui_story_5060_50601101_26_dialog_content = "Saya tidak berpikir ini semua salahmu, Pak Liu.",
  ui_story_5060_50601101_27_dialog_content = "Makanan yang kamu buat benar-benar lezat! Tidak mungkin kamu salah di sini!",
  ui_story_5060_50601101_28_dialog_content = "Ini semua karena bangsawan Lumo yang fanatik dan prajurit pribadi mereka! Seseorang harus menghentikan mereka!",
  ui_story_5060_50601101_29_option_content = "Aku bisa membantu kamu!",
  ui_story_5060_50601101_30_option_content = "Jangan khawatir, aku kenal beberapa orang.",
  ui_story_5060_50601101_31_dialog_content = "Terima kasih telah begitu menghibur.",
  ui_story_5060_50601101_32_dialog_content = "Tapi memang begitu cara dunia ini bekerja. Kemampuan saya sendiri tidak lagi cukup untuk menjalankan restoran ini, dan ini memang tak bisa dihindari.",
  ui_story_5060_50601101_33_dialog_content = "(Sepertinya Pak Liu sudah kehilangan seluruh kepercayaan pada bangsawan dan perwira militer Lumopolis...)",
  ui_story_5060_50601101_34_dialog_content = "(Tapi tetap saja, seseorang perlu melakukan sesuatu tentang sikap busuk ini.)",
  ui_story_5060_50601101_35_dialog_content = "(Saya rasa aku akan pergi bicara dengannya.)",
  ui_story_5060_50601101_36_dialog_content = "Nona Tohru, bisakah kamu mencoba berbicara dengan pemiliknya dan membujuknya?",
  ui_story_5060_50601101_37_dialog_content = "Pak Liu, memang benar bahwa saya pernah melihat beberapa Bangsawan Lumo yang memiliki pandangan diskriminatif terhadap Aurorian demi-human.",
  ui_story_5060_50601101_38_dialog_content = "Tapi di restoranmu, aku juga melihat banyak Aurorian berdarah murni, Prajurit Lumopolis, dan pedagang biasa.",
  ui_story_5060_50601101_39_dialog_content = "Dan semua mereka berkumpul di tempat ini karena dirimu!",
  ui_story_5060_50601101_40_dialog_content = "Benar sekali!",
  ui_story_5060_50601101_41_dialog_content = "Makanan memiliki kekuatan untuk menyelesaikan konflik apa pun!",
  ui_story_5060_50601101_42_dialog_content = "Itu hanya berfungsi untukmu, Elma.",
  ui_story_5060_50601101_43_dialog_content = "Tapi, makanan di sini benar-benar enak.",
  ui_story_5060_50601101_44_dialog_content = "Untuk para demi-human yang bekerja di sini, untuk banyak tamu yang tidak dikenal yang makan di sini... Dan untuk diri saya sendiri juga, restoran Anda berfungsi sebagai jembatan yang menghubungkan semua orang. Tak ada prajurit pribadi atau bangsawan yang bisa mengambil perasaan dan hubungan yang terjalin di sini!",
  ui_story_5060_50601101_45_dialog_content = "Baru saja saya selesai menceritakan kepada seorang tetua tentang kekuatan berbagai orang yang bersatu untuk berjuang demi tujuan bersama. Baik itu naga atau Aurorian, tidak ada rintangan yang terlalu besar untuk diatasi saat kita menggabungkan kekuatan kita!",
  ui_story_5060_50601101_46_dialog_content = "Saya rasa sekarang saatnya untuk memenuhi janji itu— Untuk menunjukkan bahwa kata-kata ini lebih dari sekadar kata-kata!",
  ui_story_5060_50601101_47_dialog_content = "Kata-kata yang bagus, Nona Tohru. Jika kamu pikir itu layak, akan kucoba lagi.",
  ui_story_5060_50601101_48_dialog_content = "Aku hanya berharap para bangsawan di Lumopolis bisa berhenti mengganggu kami.",
  ui_story_5060_50601101_49_dialog_content = "Dan jangan khawatir, jika kita bertemu dengan orang yang tidak mau mendengarkan alasan, aku akan mengirim mereka langsung ke neraka, gratis!",
  ui_story_5060_50601101_50_dialog_content = "Jangan terlalu terbawa suasana.",
  ui_story_5060_50601101_51_dialog_content = "Baiklah, baiklah!",
  ui_story_5060_50601101_52_dialog_content = "Aku setuju dengan pernyataan Tohru tadi.",
  ui_story_5060_50601101_53_dialog_content = "Jika kamu ingin mengubah nasib dunia, tidak ada salahnya mulai dengan mengubah nasib satu restoran saja.",
  ui_story_5060_50601101_54_dialog_content = "Dan kita bisa mulai dengan memperbaikikan, membersihkan area mang!",
  ui_story_5060_50601101_55_dialog_content = "Aku bisa membantu mengembangkan hidangan baru, jika tidak keberatan?",
  ui_story_5060_50601101_56_dialog_content = "Tidak mungkin. Kamu pasti akan memakan semuanya.",
  ui_story_5060_50601101_57_dialog_content = "Jangan khawatir, Tuan Liu.",
  ui_story_5060_50601101_58_dialog_content = "Baru saja saya berbicara dengan teman baik saya. Dia mengatakan bahwa sebagai putri City Lord, dia akan melakukan segala yang dia bisa untuk memperbaiki segalanya.",
  ui_story_5060_50601101_59_dialog_content = "Mulai sekarang, Anda tidak perlu khawatir tentang siapa pun yang mengganggu Anda atau restoran Anda lagi. Saya yakin akan hal itu.",
  ui_story_5060_50601101_60_dialog_content = "I-Ini beneran?! Astaga, aku nggak sedang bermimpi, 'kan?!",
  ui_story_5060_50601101_61_dialog_content = "Terima kasih semuanya! Aku tak bisa mengungkapkan rasa terima kasihku cukup!",
  ui_story_5060_50601101_62_dialog_content = "Ayo, hari ini semua pada saya. Semuanya, makanlah sepuasnya dan nikmati pesta ini!",
  ui_story_5060_50601101_63_dialog_content = "Tiga tamu terhormat, ini dia hidangan spesial baru kami: Sup Makanan Laut Emas. Hati-hati dengan panasnya.",
  ui_story_5060_50601101_64_dialog_content = "Tentu saja, ini akan selesai sebentar lagi. Silakan tunggu sebentar.",
  ui_story_5060_50601101_65_dialog_content = "Meja lima, satu porsi Tahu Salju!",
  ui_story_5060_50601101_66_dialog_content = "Tempat ini benar-benar sibuk! Jelas bahwa semua orang di sini menyukai makanannya.",
  ui_story_5060_50601101_67_dialog_content = "Sepertinya Pak Liu hanya mencari alasan sebelumnya. Masalah sebenarnya adalah semua pelecehan yang datang dari para bangsawan dan prajurit pribadi itu.",
  ui_story_5060_50601101_68_dialog_content = "Baguslah, orang-orang itu tidak akan jadi masalah lagi.",
  ui_story_5060_50601101_69_dialog_content = "Tidak bisa lebih baik lagi!",
  ui_story_5060_50601101_70_dialog_content = "Kamu yakin tidak terburu-buru untuk kembali, Nona Tohru? Saya cukup yakin ayahmu masih menunggumu.",
  ui_story_5060_50601101_71_dialog_content = "Tidak apa-apa, aku masih ingin melihat lebih banyak dari dunia ini.",
  ui_story_5060_50601101_72_dialog_content = "Ada begitu banyak keindahan di duniamu, dan ternyata tidak seberbahaya yang kusangka sebelumnya.",
  ui_story_5060_50601101_73_dialog_content = "Tapi mungkin itu hanya karena aku punya kamu, Elma, dan yang lain bersamaku sepanjang waktu, PlayerName.",
  ui_story_5060_50601101_74_dialog_content = "Kamu yakin bisa kembali?",
  ui_story_5060_50601101_75_dialog_content = "Merasa ragu pada kata-kata temanmu begitu cepat, PlayerName?",
  ui_story_5060_50601101_76_dialog_content = "Hahaha, cuma bercanda! Jangan khawatir, saya yakin kita akan kembali dalam waktu dekat.",
  ui_story_5060_50601101_77_dialog_content = "Kami akan segera menemui kamu setelah kami kembali!",
  ui_story_5060_50601101_78_dialog_content = "Aku tak sabar menantikannya, tapi jangan terlalu lama ya? Toh...",
  ui_story_5060_50601101_79_dialog_content = "Kita berteman seumur hidup sekarang.",
  ui_story_5060_50601101_80_dialog_content = "PlayerName!",
  ui_story_5060_50601101_81_dialog_content = "Aaaah— Minggir!!",
  ui_story_5060_50601101_82_dialog_content = "Ada apa, Vice? Mengapa kamu panik seperti itu?",
  ui_story_5060_50601101_83_dialog_content = "Sepertinya kursus pelatihan Anda di Illumina telah berakhir lebih awal.",
  ui_story_5060_50601101_84_dialog_content = "Itu karena ada yang bilang kamu dalam bahaya! Aku segera berlari ke sini begitu mendengarnya!!",
  ui_story_5060_50601101_85_dialog_content = "Kamu tidak terluka, kan?!",
  ui_story_5060_50601101_86_option_content = "Tenang, aku benar-benar baik-baik saja.",
  ui_story_5060_50601101_87_dialog_content = "Aku lega sekali.",
  ui_story_5060_50601101_88_option_content = "Aku cukup terluka.",
  ui_story_5060_50601101_89_dialog_content = "Kamu tadi nabrak aku keras banget sampai kepalaku jadi agak sakit.",
  ui_story_5060_50601101_90_dialog_content = "Kalau begitu, biarkan aku menggosoknya untukmu!",
  ui_story_5060_50601101_91_dialog_content = "Dan semua rasa sakit dan nyeri akan hilang!",
  ui_story_5060_50601101_92_dialog_content = "Oke, aku merasa lebih baik sekarang.",
  ui_story_5060_50601101_93_dialog_content = "Hey PlayerName, apa itu di tanganmu?",
  ui_story_5060_50601101_94_dialog_content = "Oh, hanya hadiah dari seorang teman.",
  ui_story_5060_50601101_95_dialog_content = "Aku mendapat beberapa teman baru saat kamu pergi. Mereka sudah pergi, tapi aku yakin kita akan bertemu mereka lagi sebentar lagi.",
  ui_story_5060_50601101_96_dialog_content = "Mereka adalah sekelompok orang baik, sangat baik, sungguh."
}
return config
